      { id: "ZERO", exitDate: "2026-01-03", returnPct: 0, confidence: 42 },
      { symbol: "NEG", entryDate: "2026-01-02", returnPct: -2, signalConfidence: 74 },
      { returnPct: 1.5 },
    ],
  });
  const decision = classifyStrategySignal({
    readiness: { ...result, calibration: undefined as any },
    rawAction: "Buy",
