  },
  other: {
    title: "Resolve uncategorized readiness blocker",
    baseLift: 5,
    effort: "medium",
    targetScore: 65,
    evidenceRequired: ["Blocking evidence", "Owner diagnosis"],
    unlocks: ["Readiness can be reassessed after the blocker is classified."],
  },
};

const SEVERITY_WEIGHT: Record<ReadinessRemediationSeverity, number> = {
  low: 2,
  medium: 5,
  high: 9,
  critical: 14,
};

export function planReadinessRemediation(input: ReadinessRemediationInput = {}): ReadinessRemediationPlan {
  const gates = Array.isArray(input.gates) ? input.gates : [];
  const flags = Array.isArray(input.failureFlags) ? input.failureFlags.filter(Boolean) : [];
  const candidates = [
    ...gates.flatMap(gateCandidate),
    ...flags.map(flagCandidate),
    ...trustCandidates(input.trust),
    ...calibrationCandidates(input.calibration),
    ...robustnessCandidates(input.robustness),
    ...contextCandidates(input.context),
  ];
  const steps = mergeCandidates(candidates)
    .map(candidateToStep)
    .sort(compareSteps)
    .map((step, index) => ({ ...step, priority: index + 1 }));
  const failedGateCount = gates.filter((gate) => gate.passed === false).length;
  const totalExpectedTrustLift = round(clamp(steps.slice(0, 4).reduce((sum, step) => sum + step.expectedTrustLift, 0)));
  const executionGate = executionGateFor(steps, input.trust?.participationMode, input.context?.allowsNewExposure);
  const status = statusFor(steps, executionGate);
  const blockers = steps
    .filter((step) => step.status === "blocked" || step.severity === "high" || step.severity === "critical")
    .map((step) => step.reason)
    .slice(0, 6);
  const topAction = steps[0]?.title ?? "No remediation required";

  return {
    module: "signal.readiness-remediation-planner",
    name: "Readiness Remediation Planner",
    status,
    summary: summaryFor(status, steps, totalExpectedTrustLift),
    topAction,
    totalExpectedTrustLift,
    executionGate,
    ...(input.context?.targetStage ? { targetStage: String(input.context.targetStage) } : {}),
    steps,
    blockers,
    audit: {
      inputGateCount: gates.length,
      failedGateCount,
      failureFlagCount: flags.length,
      formulas: [
        "candidate severity comes from failed gates, failure flags, calibration, robustness, trust blockers, and capacity context",
        "expectedTrustLift = category base lift + severity weight + score deficit / 5 + primary trust blocker bonus",
        "priority sorts by blocked status, expected trust lift, severity, and stable category order",
      ],
    },
  };
}

export const planReadinessRemediationSteps = planReadinessRemediation;

function gateCandidate(gate: ReadinessRemediationGate): Candidate[] {
  const passed = gate.passed === true || normalizedSeverity(gate.severity) === "low" && numeric(gate.score, 100) >= numeric(gate.targetScore, 70);
  if (passed) return [];

  const category = gate.category ?? categoryFromText(`${gate.id} ${gate.label ?? ""}`);
  const defaults = CATEGORY_DEFAULTS[category];
  const currentScore = finiteOrNull(gate.score);
  const targetScore = numeric(gate.targetScore, defaults.targetScore);

  return [{
    id: `gate:${gate.id}`,
    category,
    title: defaults.title,
    severity: gate.severity ?? severityFromScore(currentScore, targetScore),
    reason: gate.reason || `${gate.label ?? gate.id} has not cleared the readiness threshold.`,
    currentScore,
    targetScore,
    evidenceRequired: gate.evidenceRequired ?? defaults.evidenceRequired,
    unlocks: gate.unlockCriteria ?? defaults.unlocks,
    sourceId: gate.id,
    trustPrimary: false,
  }];
}

function flagCandidate(flag: string): Candidate {
  const category = categoryFromText(flag);
  const defaults = CATEGORY_DEFAULTS[category];
  const severity = /DATA|EXECUTION_BLOCKED|BLOCK|ROBUSTNESS|BENCHMARK/.test(normalizedCode(flag)) ? "high" : "medium";

  return {
    id: `flag:${normalizedCode(flag)}`,
    category,
    title: defaults.title,
    severity,
    reason: reasonForFlag(flag, defaults.title),
    currentScore: null,
    targetScore: defaults.targetScore,
    evidenceRequired: defaults.evidenceRequired,
    unlocks: defaults.unlocks,
    sourceId: normalizedCode(flag),
    trustPrimary: false,
  };
}

function trustCandidates(trust: ReadinessRemediationInput["trust"]): Candidate[] {
  if (!trust) return [];

  const primary = String(trust.primaryBlocker ?? "");
  const blockers = Array.isArray(trust.blockers) ? trust.blockers : [];

  return blockers.map((item, index) => {
    const category = categoryFromText(`${item.id ?? ""} ${item.label ?? ""} ${item.reason ?? ""}`);
    const defaults = CATEGORY_DEFAULTS[category];
    const id = String(item.id ?? `trust-${index}`);

    return {
      id: `trust:${id}`,
      category,
      title: defaults.title,
      severity: normalizedSeverity(item.severity),
      reason: item.reason || item.label || "Trust Governor blocks increased participation.",
      currentScore: finiteOrNull(trust.trustScore),
      targetScore: defaults.targetScore,
      evidenceRequired: defaults.evidenceRequired,
      unlocks: item.unlockCriteria ?? trust.unlockCriteria ?? defaults.unlocks,
      sourceId: id,
      trustPrimary: id === primary || normalizedCode(id) === normalizedCode(primary),
    };
  });
}

function calibrationCandidates(calibration: ReadinessRemediationInput["calibration"]): Candidate[] {
  if (!calibration) return [];

  const status = normalizedCode(calibration.status ?? "");
  const warnings = (calibration.warnings ?? []).map(normalizedCode);
  const needsReview =
    status.includes("UNSTABLE") ||
    status.includes("POOR") ||
    status.includes("INSUFFICIENT") ||
    warnings.some((warning) => warning.includes("UNSTABLE") || warning.includes("OVERCONFIDENCE") || warning.includes("POOR"));

  if (!needsReview) return [];

  const raw = finiteOrNull(calibration.rawConfidence);
  const calibrated = finiteOrNull(calibration.calibratedConfidence);
  const gap = raw != null && calibrated != null ? Math.max(0, raw - calibrated) : 0;
  const severity: ReadinessRemediationSeverity = status.includes("INSUFFICIENT")
    ? "medium"
    : gap >= 20 || status.includes("UNSTABLE")
      ? "high"
      : "medium";
  const defaults = CATEGORY_DEFAULTS.calibration;

  return [{
    id: `calibration:${status || "warnings"}`,
    category: "calibration",
    title: defaults.title,
    severity,
    reason: status.includes("UNSTABLE")
      ? "Calibration has samples, but outcomes are unstable."
      : status.includes("INSUFFICIENT")
        ? "Calibration history is not deep enough yet."
        : "Calibration quality does not support higher trust yet.",
    currentScore: finiteOrNull(calibration.trustworthiness ?? calibrated),
    targetScore: defaults.targetScore,
    evidenceRequired: defaults.evidenceRequired,
    unlocks: defaults.unlocks,
    sourceId: status || "calibration",
    trustPrimary: false,
  }];
}

function robustnessCandidates(robustness: ReadinessRemediationInput["robustness"]): Candidate[] {
  if (!robustness) return [];

  const overfitRisk = finiteOrNull(robustness.overfitRisk ?? robustness.overfitRiskPct);
  const deploymentReadiness = finiteOrNull(robustness.deploymentReadiness ?? robustness.deploymentReadinessScore);
  const safetyGate = normalizedCode(robustness.safetyGate ?? "");
  const blocked = safetyGate.includes("BLOCK");
  const risky = blocked || (overfitRisk != null && overfitRisk > 30) || (deploymentReadiness != null && deploymentReadiness < 60);

  if (!risky) return [];

  const defaults = CATEGORY_DEFAULTS.robustness;

  return [{
    id: "robustness:overfit",
    category: "robustness",
    title: defaults.title,
    severity: blocked || (overfitRisk != null && overfitRisk > 60) ? "critical" : "high",
    reason: blocked
      ? "Robustness safety gate blocks execution."
      : "Robustness overfit risk is above the execution threshold.",
    currentScore: overfitRisk == null ? finiteOrNull(robustness.robustnessScore) : clamp(100 - overfitRisk),
    targetScore: defaults.targetScore,
    evidenceRequired: defaults.evidenceRequired,
    unlocks: defaults.unlocks,
    sourceId: "robustness",
    trustPrimary: false,
  }];
}

function contextCandidates(context: ReadinessRemediationInput["context"]): Candidate[] {
  if (!context) return [];

  const maxConfidence = finiteOrNull(context.maxConfidence);
  const readinessScore = finiteOrNull(context.readinessScore);
  const confidenceBlocked = maxConfidence != null && maxConfidence < 50;
  const readinessBlocked = readinessScore != null && readinessScore < 50;

  if (!confidenceBlocked && !readinessBlocked && context.allowsNewExposure !== false) return [];

  const category: ReadinessRemediationCategory = context.allowsNewExposure === false ? "capacity" : "strategy_edge";
  const defaults = CATEGORY_DEFAULTS[category];

  return [{
    id: `context:${category}`,
    category,
    title: defaults.title,
    severity: confidenceBlocked || readinessBlocked ? "medium" : "high",
    reason: context.allowsNewExposure === false
      ? "The current state does not allow new exposure."
      : "Readiness or confidence is below the review threshold.",
    currentScore: readinessScore ?? maxConfidence,
    targetScore: defaults.targetScore,
    evidenceRequired: defaults.evidenceRequired,
    unlocks: defaults.unlocks,
    sourceId: category,
    trustPrimary: false,
  }];
}

function mergeCandidates(candidates: Candidate[]): Candidate[] {
  const merged = new Map<ReadinessRemediationCategory, Candidate>();

  for (const candidate of candidates) {
    const existing = merged.get(candidate.category);

    if (!existing) {
      merged.set(candidate.category, candidate);
      continue;
    }

    merged.set(candidate.category, {
      ...existing,
      severity: strongerSeverity(existing.severity, candidate.severity),
      reason: existing.trustPrimary ? existing.reason : candidate.trustPrimary ? candidate.reason : existing.reason,
      currentScore: lowerNullable(existing.currentScore, candidate.currentScore),
      targetScore: Math.max(existing.targetScore, candidate.targetScore),
      evidenceRequired: unique([...existing.evidenceRequired, ...candidate.evidenceRequired]),
      unlocks: unique([...existing.unlocks, ...candidate.unlocks]),
      sourceId: unique([existing.sourceId, candidate.sourceId]).join(","),
      trustPrimary: existing.trustPrimary || candidate.trustPrimary,
    });
  }

  return Array.from(merged.values());
}

function candidateToStep(candidate: Candidate): ReadinessRemediationStep {
  const defaults = CATEGORY_DEFAULTS[candidate.category];
  const deficit = candidate.currentScore == null ? 20 : Math.max(0, candidate.targetScore - candidate.currentScore);
  const expectedTrustLift = round(clamp(defaults.baseLift + SEVERITY_WEIGHT[candidate.severity] + deficit / 5 + (candidate.trustPrimary ? 6 : 0), 1, 35));

  return {
    id: `remediate:${candidate.category}`,
    category: candidate.category,
    title: candidate.title,
    priority: 0,
    severity: candidate.severity,
    status: candidate.severity === "critical" || candidate.severity === "high"
      ? "blocked"
      : candidate.severity === "medium"
        ? "review"
        : "watch",
    expectedTrustLift,
    effort: defaults.effort,
    reason: candidate.reason,
    evidenceRequired: unique(candidate.evidenceRequired),
    unlocks: unique(candidate.unlocks),
    sourceIds: candidate.sourceId.split(",").filter(Boolean),
    metrics: {
      currentScore: candidate.currentScore,
      targetScore: candidate.targetScore,
      deficit: round(deficit),
    },
  };
}

function compareSteps(left: ReadinessRemediationStep, right: ReadinessRemediationStep) {
  const statusDelta = statusRank(right.status) - statusRank(left.status);
  if (statusDelta !== 0) return statusDelta;

  const liftDelta = right.expectedTrustLift - left.expectedTrustLift;
  if (liftDelta !== 0) return liftDelta;

  const severityDelta = SEVERITY_WEIGHT[right.severity] - SEVERITY_WEIGHT[left.severity];
  if (severityDelta !== 0) return severityDelta;

  return categoryRank(left.category) - categoryRank(right.category);
}

function executionGateFor(
  steps: ReadinessRemediationStep[],
  participationMode: string | undefined,
  allowsNewExposure: boolean | undefined,
): ReadinessRemediationPlan["executionGate"] {
  const mode = normalizedCode(participationMode ?? "");
  if (allowsNewExposure === false || mode.includes("BLOCKED") || steps.some((step) => step.severity === "critical")) {
    return "blocked";
  }
  if (mode.includes("EXITS_ONLY") || mode.includes("PAPER") || steps.some((step) => step.status === "blocked")) {
    return "review";
  }
  return "open";
}

function statusFor(steps: ReadinessRemediationStep[], gate: ReadinessRemediationPlan["executionGate"]): ReadinessRemediationStatus {
  if (!steps.length) return "ready";
  if (gate === "blocked") return "blocked";
  if (gate === "review") return "review";
  return "watch";
}

function summaryFor(status: ReadinessRemediationStatus, steps: ReadinessRemediationStep[], lift: number) {
  if (status === "ready") return "No readiness remediation is required.";
  const first = steps[0];
  return `${first.title} is the highest-impact remediation step, with an estimated trust lift of ${lift.toFixed(1)} points across the top priorities.`;
}

function reasonForFlag(flag: string, fallbackTitle: string) {
  const code = normalizedCode(flag);
  if (code.includes("LOW_SHARPE")) return "Risk-adjusted return is below the readiness threshold.";
  if (code.includes("BENCHMARK")) return "The objective does not clear the benchmark margin.";
  if (code.includes("WALK_FORWARD")) return "Walk-forward outcomes are not stable enough.";
  if (code.includes("PARAMETER")) return "Nearby variants do not preserve the edge.";
  if (code.includes("OUTLIER") || code.includes("CONCENTRATION") || code.includes("TOP_WINNER")) return "Returns depend too heavily on concentrated winners or periods.";
  if (code.includes("ROBUSTNESS")) return "Robustness risk blocks higher trust.";
  if (code.includes("CALIBRATION")) return "Calibration does not support higher trust yet.";
  if (code.includes("DATA") || code.includes("SYNTHETIC")) return "Data quality is not reliable enough for promotion.";
  if (code.includes("LIVE_SIGNAL") || code.includes("FORWARD_SHADOW")) return "Live or forward evidence is not sufficient yet.";
  if (code.includes("DRAWDOWN") || code.includes("RISK")) return "Risk control is below threshold.";
  return `${fallbackTitle} is required before readiness can improve.`;
}

function categoryFromText(value: string): ReadinessRemediationCategory {
  const code = normalizedCode(value);
  if (code.includes("CALIBRATION")) return "calibration";
  if (code.includes("ROBUSTNESS") || code.includes("OVERFIT")) return "robustness";
  if (code.includes("BENCHMARK")) return "benchmark";
  if (code.includes("WALK_FORWARD") || code.includes("PERIOD")) return "walk_forward";
  if (code.includes("SHARPE") || code.includes("STRATEGY_EDGE") || code.includes("RISK_ADJUSTED")) return "strategy_edge";
  if (code.includes("PARAMETER") || code.includes("VARIANT")) return "parameter_stability";
  if (code.includes("OUTLIER") || code.includes("CONCENTRATION") || code.includes("TOP_WINNER")) return "concentration";
  if (code.includes("DATA") || code.includes("SYNTHETIC") || code.includes("STALE")) return "data_reliability";
  if (code.includes("LIVE_SIGNAL") || code.includes("FORWARD_SHADOW") || code.includes("SIGNAL_MATCH")) return "live_signal";
  if (code.includes("DRAWDOWN") || code.includes("RISK_CONTROL")) return "risk_control";
  if (code.includes("CAPACITY") || code.includes("EXPOSURE")) return "capacity";
  if (code.includes("BELIEF")) return "belief";
  if (code.includes("JUDGEMENT") || code.includes("JUDGMENT")) return "judgement";
  if (code.includes("AGENCY")) return "agency";
  return "other";
}

function normalizedSeverity(value: unknown): ReadinessRemediationSeverity {
  const text = String(value ?? "").toLowerCase();
  if (text === "critical") return "critical";
  if (text === "high" || text === "bad") return "high";
  if (text === "low" || text === "good") return "low";
  return "medium";
}

function severityFromScore(score: number | null, target: number): ReadinessRemediationSeverity {
  if (score == null) return "medium";
  const deficit = target - score;
  if (deficit >= 45) return "critical";
  if (deficit >= 20) return "high";
  if (deficit > 0) return "medium";
  return "low";
}

function strongerSeverity(left: ReadinessRemediationSeverity, right: ReadinessRemediationSeverity) {
  return SEVERITY_WEIGHT[right] > SEVERITY_WEIGHT[left] ? right : left;
}

function lowerNullable(left: number | null, right: number | null) {
  if (left == null) return right;
  if (right == null) return left;
  return Math.min(left, right);
}

function categoryRank(category: ReadinessRemediationCategory) {
  return Object.keys(CATEGORY_DEFAULTS).indexOf(category);
}

function statusRank(status: Exclude<ReadinessRemediationStatus, "ready">) {
  if (status === "blocked") return 3;
  if (status === "review") return 2;
  return 1;
}

function normalizedCode(value: unknown) {
  return String(value)
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_");
}

function finiteOrNull(value: unknown) {
  const n = Number(value);
  return Number.isFinite(n) ? clamp(n) : null;
}

function unique(values: string[]) {
  return Array.from(new Set(values.filter(Boolean)));
}

/* c8 ignore next: tsx sourcemaps emit a phantom branch for this helper binding. */
const round = (value: number) => Number(value.toFixed(2));

/* c8 ignore next */
import { clamp } from "../math/statistics";

export type RecoveryStatus = "locked" | "recovering" | "restored" | "regressed";
export type RecoveryMode = "observe" | "reduced-size" | "graduated" | "normal";

export type RecoveryThresholds = {
  minSurvivalConfidenceForRecovery: number;
  minSurvivalConfidenceForRestore: number;
  minTrustScoreForRestore: number;
  minCalibratedConfidenceForRestore: number;
  minRecoveryScoreForRecovery: number;
  minRecoveryScoreForGraduated: number;
  minRecoveryScoreForRestore: number;
  minDataReliability: number;
  maxOverfitRisk: number;
  regressedOverfitRisk: number;
  maxBeliefFragilityForRestore: number;
  minEvidenceAgreementForRestore: number;
  minDiscoveryConfidenceForRestore: number;
  minDiscoveryMaturityForRestore: number;
  minJudgementReliabilityForRestore: number;
  minOutcomeStabilityForRestore: number;
  minSimilarSamplesForRestore: number;
  minPositiveOutcomeRatioForRestore: number;
  maxConfidenceCapLift: number;
  agencyReviewBlocksRestore: boolean;
};

export type RecoveryInput = {
  survivalConfidence?: number | null;
  scarCount?: number | null;
  nearRuinCount?: number | null;
  currentStateSimilarity?: number | null;
  recoveryExposureCap?: number | null;
  trustScore?: number | null;
  confidenceCap?: number | null;
  calibratedConfidence?: number | null;
  rawConfidence?: number | null;
  judgementReliability?: number | null;
  similarSampleCount?: number | null;
  positiveSimilarOutcomes?: number | null;
  negativeSimilarOutcomes?: number | null;
  neutralSimilarOutcomes?: number | null;
  outcomeStability?: number | null;
  overfitRisk?: number | null;
  beliefFragility?: number | null;
  evidenceAgreement?: number | null;
  dataReliability?: number | null;
  blockedAgencyActionCount?: number | null;
  discoveryConfidence?: number | null;
  discoveryMaturity?: number | null;
  novelty?: number | null;
  currentSizingMode?: string | null;
  currentMaxExposure?: number | null;
  targetNormalExposure?: number | null;
  thresholds?: Partial<RecoveryThresholds>;
};

export type RecoveryResult = {
  module: "signal.recovery";
  name: "Signal Recovery";
  status: RecoveryStatus;
  mode: RecoveryMode;
  recoveryScore: number;
  trustedCapacity: number;
  confidenceCapLift: number;
  recommendedExposureCap: number;
  canRestoreSizing: boolean;
  shouldEscalateHumanReview: boolean;
  reasons: string[];
  blockers: string[];
  unlockConditions: string[];
  invalidationConditions: string[];
  audit: {
    thresholds: RecoveryThresholds;
    normalized: {
      survivalConfidence: number;
      scarPressure: number;
      nearRuinPressure: number;
      currentStateSimilarity: number;
      trustScore: number;
      confidenceCap: number;
      calibratedConfidence: number;
      rawConfidence: number;
      judgementReliability: number;
      outcomeStability: number;
      overfitRisk: number;
      beliefFragility: number;
      evidenceAgreement: number;
      dataReliability: number;
      blockedAgencyActionCount: number;
      discoveryConfidence: number;
      discoveryMaturity: number;
      novelty: number;
      currentMaxExposure: number;
      targetNormalExposure: number;
    };
    positiveOutcomeRatio: number;
    sampleConfidence: number;
    evidenceLift: number;
    trustLift: number;
    discoveryLift: number;
    damagePenalty: number;
    riskPenalty: number;
    agencyPenalty: number;
    noveltyPenalty: number;
    recoveryScoreBeforeClamp: number;
    currentCapacityRatio: number;
    formulas: string[];
  };
};

export const DEFAULT_RECOVERY_THRESHOLDS: RecoveryThresholds = {
  minSurvivalConfidenceForRecovery: 45,
  minSurvivalConfidenceForRestore: 70,
  minTrustScoreForRestore: 70,
  minCalibratedConfidenceForRestore: 65,
  minRecoveryScoreForRecovery: 45,
  minRecoveryScoreForGraduated: 62,
  minRecoveryScoreForRestore: 76,
  minDataReliability: 70,
  maxOverfitRisk: 35,
  regressedOverfitRisk: 50,
  maxBeliefFragilityForRestore: 35,
  minEvidenceAgreementForRestore: 65,
  minDiscoveryConfidenceForRestore: 50,
  minDiscoveryMaturityForRestore: 50,
  minJudgementReliabilityForRestore: 70,
  minOutcomeStabilityForRestore: 65,
  minSimilarSamplesForRestore: 100,
  minPositiveOutcomeRatioForRestore: 0.65,
  maxConfidenceCapLift: 15,
  agencyReviewBlocksRestore: true,
};

export function evaluateRecovery(input: RecoveryInput = {}): RecoveryResult {
  const thresholds = { ...DEFAULT_RECOVERY_THRESHOLDS, ...(input.thresholds ?? {}) };
  const survivalConfidence = score(input.survivalConfidence, 0);
  const scarPressure = countPressure(input.scarCount, 100);
  const nearRuinPressure = countPressure(input.nearRuinCount, 50);
  const currentStateSimilarity = score(input.currentStateSimilarity, 0);
  const trustScore = score(input.trustScore, 50);
  const confidenceCap = score(input.confidenceCap, trustScore);
  const calibratedConfidence = score(input.calibratedConfidence, confidenceCap);
  const rawConfidence = score(input.rawConfidence, calibratedConfidence);
  const judgementReliability = score(input.judgementReliability, 50);
  const outcomeStability = score(input.outcomeStability, judgementReliability);
  const overfitRisk = score(input.overfitRisk, 100);
  const beliefFragility = score(input.beliefFragility, 50);
  const evidenceAgreement = score(input.evidenceAgreement, 50);
  const dataReliability = score(input.dataReliability, 0);
  const blockedAgencyActionCount = Math.max(0, Math.round(number(input.blockedAgencyActionCount, 0)));
  const discoveryConfidence = score(input.discoveryConfidence, 0);
  const discoveryMaturity = score(input.discoveryMaturity, 0);
  const novelty = score(input.novelty, 50);
  const currentMaxExposure = percent(input.currentMaxExposure, percent(input.recoveryExposureCap, 0));
  const targetNormalExposure = Math.max(
    0,
    percent(input.targetNormalExposure, Math.max(currentMaxExposure, percent(input.recoveryExposureCap, currentMaxExposure))),
  );
  const currentCapacityRatio = targetNormalExposure > 0 ? clamp(currentMaxExposure / targetNormalExposure * 100) : 0;
  const sampleCount = Math.max(0, Math.round(number(input.similarSampleCount, 0)));
  const positiveOutcomes = Math.max(0, Math.round(number(input.positiveSimilarOutcomes, 0)));
  const negativeOutcomes = Math.max(0, Math.round(number(input.negativeSimilarOutcomes, 0)));
  const neutralOutcomes = Math.max(0, Math.round(number(input.neutralSimilarOutcomes, 0)));
  const outcomeCount = positiveOutcomes + negativeOutcomes + neutralOutcomes;
  const positiveOutcomeRatio = outcomeCount > 0 ? positiveOutcomes / outcomeCount : 0;
  const sampleConfidence = clamp(sampleCount / Math.max(1, thresholds.minSimilarSamplesForRestore) * 100);
  const evidenceLift = round(
    Math.max(0, judgementReliability - 60) * 0.16 +
      Math.max(0, outcomeStability - 60) * 0.16 +
      Math.max(0, evidenceAgreement - 60) * 0.12 +
      Math.max(0, positiveOutcomeRatio * 100 - 55) * 0.25 +
      Math.max(0, sampleConfidence - 50) * 0.08,
  );
  const trustLift = round(
    Math.max(0, trustScore - 60) * 0.1 +
      Math.max(0, confidenceCap - 60) * 0.08 +
      Math.max(0, calibratedConfidence - 60) * 0.08 +
      Math.max(0, rawConfidence - calibratedConfidence) * 0.03 +
      Math.max(0, dataReliability - 80) * 0.12,
  );
  const discoveryLift = round(
    Math.max(0, discoveryConfidence - 45) * 0.07 +
      Math.max(0, discoveryMaturity - 45) * 0.07,
  );
  const damagePenalty = round(
    scarPressure * 0.05 +
      nearRuinPressure * 0.07 +
      currentStateSimilarity * 0.06,
  );
  const riskPenalty = round(
    overfitRisk * 0.2 +
      beliefFragility * 0.1 +
      Math.max(0, thresholds.minDataReliability - dataReliability) * 0.35,
  );
  const agencyPenalty = round(Math.min(blockedAgencyActionCount, 6) * 1.5);
  const noveltyPenalty = round(
    Math.max(0, novelty - 50) * 0.03 +
      Math.max(0, 50 - discoveryMaturity) * 0.1 +
      Math.max(0, 50 - discoveryConfidence) * 0.08,
  );
  const recoveryScoreBeforeClamp = round(
    survivalConfidence +
      evidenceLift +
      trustLift +
      discoveryLift -
      damagePenalty -
      riskPenalty -
      agencyPenalty -
      noveltyPenalty,
  );
  const recoveryScore = round(clamp(recoveryScoreBeforeClamp));
  const blockers = blockersFor({
    thresholds,
    survivalConfidence,
    dataReliability,
    overfitRisk,
    blockedAgencyActionCount,
    recoveryScore,
    trustScore,
    calibratedConfidence,
    beliefFragility,
    evidenceAgreement,
    judgementReliability,
    outcomeStability,
    sampleCount,
    positiveOutcomeRatio,
    discoveryConfidence,
    discoveryMaturity,
  });
  const shouldEscalateHumanReview = thresholds.agencyReviewBlocksRestore && blockedAgencyActionCount > 0;
  const status = statusFor({
    thresholds,
    survivalConfidence,
    dataReliability,
    overfitRisk,
    recoveryScore,
    canRestoreEvidence: restoreEvidencePasses({
      thresholds,
      survivalConfidence,
      trustScore,
      calibratedConfidence,
      beliefFragility,
      evidenceAgreement,
      judgementReliability,
      outcomeStability,
      sampleCount,
      positiveOutcomeRatio,
      discoveryConfidence,
      discoveryMaturity,
    }),
    shouldEscalateHumanReview,
  });
  const mode = modeFor(status, recoveryScore, thresholds);
  const trustedCapacity = trustedCapacityFor({
    status,
    mode,
    recoveryScore,
    survivalConfidence,
    currentCapacityRatio,
    thresholds,
  });
  const recommendedExposureCap = recommendedExposureCapFor({
    status,
    currentMaxExposure,
    targetNormalExposure,
    trustedCapacity,
  });
  const confidenceCapLift = confidenceCapLiftFor({
    status,
    recoveryScore,
    confidenceCap,
    currentCapacityRatio,
    trustedCapacity,
    thresholds,
  });
  const canRestoreSizing = status === "restored" && !shouldEscalateHumanReview;

  return {
    module: "signal.recovery",
    name: "Signal Recovery",
    status,
    mode,
    recoveryScore,
    trustedCapacity,
    confidenceCapLift,
    recommendedExposureCap,
    canRestoreSizing,
    shouldEscalateHumanReview,
    reasons: reasonsFor(status, mode, recoveryScore, confidenceCapLift, recommendedExposureCap, shouldEscalateHumanReview),
    blockers,
    unlockConditions: unlockConditionsFor(blockers, thresholds),
    invalidationConditions: invalidationConditionsFor(status),
    audit: {
      thresholds,
      normalized: {
        survivalConfidence,
        scarPressure,
        nearRuinPressure,
        currentStateSimilarity,
        trustScore,
        confidenceCap,
        calibratedConfidence,
        rawConfidence,
        judgementReliability,
        outcomeStability,
        overfitRisk,
        beliefFragility,
        evidenceAgreement,
        dataReliability,
        blockedAgencyActionCount,
        discoveryConfidence,
        discoveryMaturity,
        novelty,
        currentMaxExposure,
        targetNormalExposure,
      },
      positiveOutcomeRatio: roundRatio(positiveOutcomeRatio),
      sampleConfidence: round(sampleConfidence),
      evidenceLift,
      trustLift,
      discoveryLift,
      damagePenalty,
      riskPenalty,
      agencyPenalty,
      noveltyPenalty,
      recoveryScoreBeforeClamp,
      currentCapacityRatio: round(currentCapacityRatio),
      formulas: [
        "recoveryScore starts from survival confidence, then adds evidence, trust, and discovery lift",
        "damage, overfit, fragility, blocked agency actions, novelty, and immature discovery reduce recoveryScore",
        "trustedCapacity converts recoveryScore into a gradual capacity percentage while survival confidence is below restoration threshold",
        "recovery can recommend cap lift, but final execution must still pass external sizing, agency, resolve, and risk gates",
      ],
    },
  };
}

function statusFor(input: {
  thresholds: RecoveryThresholds;
  survivalConfidence: number;
  dataReliability: number;
  overfitRisk: number;
  recoveryScore: number;
  canRestoreEvidence: boolean;
  shouldEscalateHumanReview: boolean;
}): RecoveryStatus {
  if (input.dataReliability < input.thresholds.minDataReliability) return "locked";
  if (input.overfitRisk >= input.thresholds.regressedOverfitRisk) return "regressed";
  if (input.overfitRisk > input.thresholds.maxOverfitRisk) return "locked";
  if (input.survivalConfidence < input.thresholds.minSurvivalConfidenceForRecovery) return "locked";
  if (
    input.canRestoreEvidence &&
    input.recoveryScore >= input.thresholds.minRecoveryScoreForRestore &&
    !input.shouldEscalateHumanReview
  ) {
    return "restored";
  }
  if (input.recoveryScore >= input.thresholds.minRecoveryScoreForRecovery) return "recovering";
  return "locked";
}

function restoreEvidencePasses(input: {
  thresholds: RecoveryThresholds;
  survivalConfidence: number;
  trustScore: number;
  calibratedConfidence: number;
  beliefFragility: number;
  evidenceAgreement: number;
  judgementReliability: number;
  outcomeStability: number;
  sampleCount: number;
  positiveOutcomeRatio: number;
  discoveryConfidence: number;
  discoveryMaturity: number;
}) {
  return (
    input.survivalConfidence >= input.thresholds.minSurvivalConfidenceForRestore &&
    input.trustScore >= input.thresholds.minTrustScoreForRestore &&
    input.calibratedConfidence >= input.thresholds.minCalibratedConfidenceForRestore &&
    input.beliefFragility <= input.thresholds.maxBeliefFragilityForRestore &&
    input.evidenceAgreement >= input.thresholds.minEvidenceAgreementForRestore &&
    input.judgementReliability >= input.thresholds.minJudgementReliabilityForRestore &&
    input.outcomeStability >= input.thresholds.minOutcomeStabilityForRestore &&
    input.sampleCount >= input.thresholds.minSimilarSamplesForRestore &&
    input.positiveOutcomeRatio >= input.thresholds.minPositiveOutcomeRatioForRestore &&
    input.discoveryConfidence >= input.thresholds.minDiscoveryConfidenceForRestore &&
    input.discoveryMaturity >= input.thresholds.minDiscoveryMaturityForRestore
  );
}

function modeFor(status: RecoveryStatus, recoveryScore: number, thresholds: RecoveryThresholds): RecoveryMode {
  if (status === "restored") return "normal";
  if (status === "recovering") {
    return recoveryScore >= thresholds.minRecoveryScoreForGraduated ? "graduated" : "reduced-size";
  }
  return "observe";
}

function trustedCapacityFor(input: {
  status: RecoveryStatus;
  mode: RecoveryMode;
  recoveryScore: number;
  survivalConfidence: number;
  currentCapacityRatio: number;
  thresholds: RecoveryThresholds;
}) {
  if (input.status === "restored") return 100;
  if (input.status !== "recovering") return 0;

  const modeCap = input.mode === "graduated" ? 70 : 40;
  const survivalCap = input.survivalConfidence >= input.thresholds.minSurvivalConfidenceForRestore
    ? 85
    : clamp(input.survivalConfidence - 30, 0, 65);
  const evidenceCapacity = (input.recoveryScore - input.thresholds.minRecoveryScoreForRecovery) * 1.25 + input.currentCapacityRatio * 0.25 + 25;

  return round(clamp(Math.min(evidenceCapacity, modeCap, survivalCap)));
}

function recommendedExposureCapFor(input: {
  status: RecoveryStatus;
  currentMaxExposure: number;
  targetNormalExposure: number;
  trustedCapacity: number;
}) {
  if (input.status === "locked" || input.status === "regressed") return 0;
  if (input.status === "restored") return round(input.targetNormalExposure);
  const capacityCap = input.targetNormalExposure * input.trustedCapacity / 100;
  return round(Math.min(input.targetNormalExposure, Math.max(input.currentMaxExposure, capacityCap)));
}

function confidenceCapLiftFor(input: {
  status: RecoveryStatus;
  recoveryScore: number;
  confidenceCap: number;
  currentCapacityRatio: number;
  trustedCapacity: number;
  thresholds: RecoveryThresholds;
}) {
  if (input.status === "locked" || input.status === "regressed") return 0;
  const scoreLift = Math.max(0, input.recoveryScore - input.confidenceCap) * 0.45;
  const capacityLift = Math.max(0, input.trustedCapacity - input.currentCapacityRatio) * 0.08;
  return round(clamp(scoreLift + capacityLift, 0, input.thresholds.maxConfidenceCapLift));
}

function blockersFor(input: {
  thresholds: RecoveryThresholds;
  survivalConfidence: number;
  dataReliability: number;
  overfitRisk: number;
  blockedAgencyActionCount: number;
  recoveryScore: number;
  trustScore: number;
  calibratedConfidence: number;
  beliefFragility: number;
  evidenceAgreement: number;
  judgementReliability: number;
  outcomeStability: number;
  sampleCount: number;
  positiveOutcomeRatio: number;
  discoveryConfidence: number;
  discoveryMaturity: number;
}) {
  const blockers: string[] = [];
  if (input.dataReliability < input.thresholds.minDataReliability) blockers.push("Data reliability is below the recovery threshold.");
  if (input.overfitRisk > input.thresholds.maxOverfitRisk) blockers.push("Overfit risk is above the recovery threshold.");
  if (input.survivalConfidence < input.thresholds.minSurvivalConfidenceForRecovery) blockers.push("Survival confidence is too low to start recovery.");
  if (input.survivalConfidence < input.thresholds.minSurvivalConfidenceForRestore) blockers.push("Survival confidence has not cleared the normal-sizing threshold.");
  if (input.trustScore < input.thresholds.minTrustScoreForRestore) blockers.push("Trust score has not cleared the restoration threshold.");
  if (input.calibratedConfidence < input.thresholds.minCalibratedConfidenceForRestore) blockers.push("Calibrated confidence has not cleared the restoration threshold.");
  if (input.blockedAgencyActionCount > 0 && input.thresholds.agencyReviewBlocksRestore) blockers.push("Blocked agency actions require human review before restoration.");
  if (input.beliefFragility > input.thresholds.maxBeliefFragilityForRestore) blockers.push("Belief fragility is too high for normal sizing.");
  if (input.evidenceAgreement < input.thresholds.minEvidenceAgreementForRestore) blockers.push("Evidence agreement is not strong enough for restoration.");
  if (input.judgementReliability < input.thresholds.minJudgementReliabilityForRestore) blockers.push("Judgement reliability is below restoration threshold.");
  if (input.outcomeStability < input.thresholds.minOutcomeStabilityForRestore) blockers.push("Outcome stability is below restoration threshold.");
  if (input.sampleCount < input.thresholds.minSimilarSamplesForRestore) blockers.push("Similar outcome sample count is too small for restoration.");
  if (input.positiveOutcomeRatio < input.thresholds.minPositiveOutcomeRatioForRestore) blockers.push("Positive similar-outcome ratio is below restoration threshold.");
  if (input.discoveryConfidence < input.thresholds.minDiscoveryConfidenceForRestore) blockers.push("Discovery confidence has not matured enough for normal sizing.");
  if (input.discoveryMaturity < input.thresholds.minDiscoveryMaturityForRestore) blockers.push("Discovery maturity has not cleared the restoration threshold.");
  if (input.recoveryScore < input.thresholds.minRecoveryScoreForRecovery && !blockers.length) blockers.push("Recovery score is still below the recovery threshold.");
  return unique(blockers);
}

function unlockConditionsFor(blockers: string[], thresholds: RecoveryThresholds) {
  if (!blockers.length) return [];
  const unlocks: string[] = [];
  if (blockers.some((item) => item.includes("Data reliability"))) unlocks.push(`Restore data reliability to at least ${thresholds.minDataReliability}/100.`);
  if (blockers.some((item) => item.includes("Overfit"))) unlocks.push(`Reduce overfit risk to ${thresholds.maxOverfitRisk}/100 or lower.`);
  if (blockers.some((item) => item.includes("Survival confidence"))) unlocks.push(`Raise survival confidence to at least ${thresholds.minSurvivalConfidenceForRestore}/100 for normal sizing.`);
  if (blockers.some((item) => item.includes("Trust score"))) unlocks.push(`Raise trust score to at least ${thresholds.minTrustScoreForRestore}/100.`);
  if (blockers.some((item) => item.includes("Calibrated confidence"))) unlocks.push(`Raise calibrated confidence to at least ${thresholds.minCalibratedConfidenceForRestore}/100.`);
  if (blockers.some((item) => item.includes("agency"))) unlocks.push("Clear blocked agency actions or complete human review.");
  if (blockers.some((item) => item.includes("Discovery"))) unlocks.push("Let discovery confidence and maturity improve before restoring normal sizing.");
  if (!unlocks.length) unlocks.push("Keep collecting stable positive outcomes until recovery score improves.");
  return unique(unlocks);
}

function invalidationConditionsFor(status: RecoveryStatus) {
  const base = [
    "Invalidate recovery if overfit risk rises above the configured threshold.",
    "Invalidate recovery if data reliability falls below the configured threshold.",
    "Invalidate recovery if similar states repeat near-ruin survival costs.",
  ];
  if (status === "restored") return [...base, "Invalidate restoration if blocked agency actions reappear."];
  if (status === "recovering") return base;
  return ["Do not restore sizing while recovery remains locked or regressed."];
}

function reasonsFor(
  status: RecoveryStatus,
  mode: RecoveryMode,
  recoveryScore: number,
  confidenceCapLift: number,
  recommendedExposureCap: number,
  shouldEscalateHumanReview: boolean,
) {
  const reasons = [
    `Recovery is ${status} with ${mode} mode and score ${Math.round(recoveryScore)}/100.`,
  ];

  if (status === "recovering") {
    reasons.push(`Recovered evidence supports a gradual exposure cap near ${recommendedExposureCap.toFixed(2)}%.`);
  }
  if (status === "restored") {
    reasons.push("Recovery evidence supports normal sizing subject to downstream gates.");
  }
  if (confidenceCapLift > 0) {
    reasons.push(`Recovery can lift the trusted confidence cap by ${confidenceCapLift.toFixed(1)} points before downstream gates.`);
  }
  if (shouldEscalateHumanReview) {
    reasons.push("Blocked agency actions remain; human review is required before restoration.");
  }

  return reasons;
}

function countPressure(value: unknown, scale: number) {
  const count = Math.max(0, number(value, 0));
  if (count === 0) return 0;
  return clamp(Math.log1p(count) / Math.log1p(scale) * 100);
}

function score(value: unknown, fallback: number) {
  return clamp(number(value, fallback));
}

function percent(value: unknown, fallback: number) {
  return clamp(number(value, fallback), 0, 100);
}

function number(value: unknown, fallback: number) {
  if (value == null || value === "") return fallback;
  const result = Number(value);
  return Number.isFinite(result) ? result : fallback;
}

function round(value: number) {
  return Number(value.toFixed(2));
}

function roundRatio(value: number) {
  return Number(value.toFixed(4));
}

/* c8 ignore next 3 */
function unique(values: string[]) {
  return Array.from(new Set(values));
}

import type { AgencyResult } from "../agency/engine";
import type { CalibrationResult } from "../calibration/engine";
import type { JudgementResult } from "../judgement/engine";
import { clamp, mean } from "../math/statistics";
import type { ReflectionResult } from "../reflection/engine";
import type { ReliabilityResult } from "../reliability/engine";
import type { SurvivalMemoryAnalysis, SurvivalMemoryRecommendation, SurvivalMemoryStatus } from "../survival-memory/engine";

export type TrustParticipationMode =
  | "blocked"
  | "exits_only"
  | "paper"
  | "micro"
  | "limited"
  | "normal";

export type TrustGovernorAction =
  | "observe"
  | "paper_trade"
  | "risk_reducing_exits"
  | "new_exposure"
  | "increase_position";

export type TrustBlockerSeverity = "low" | "medium" | "high" | "critical";

export type TrustBlocker = {
  id: string;
  label: string;
  severity: TrustBlockerSeverity;
  reason: string;
  unlockCriteria: string[];
};

export type TrustGovernorPolicy = {
  paperTrustThreshold?: number;
  microTrustThreshold?: number;
  limitedTrustThreshold?: number;
  normalTrustThreshold?: number;
  maxRawCalibratedGap?: number;
  microMaxExposurePct?: number;
  limitedExposureMultiplier?: number;
};

export type TrustSurvivalMemoryInput = Partial<Omit<SurvivalMemoryAnalysis, "status" | "recommendation">> & {
  status?: SurvivalMemoryStatus | string;
  recommendation?: SurvivalMemoryRecommendation | string;
  maxExposurePct?: number;
};

export type TrustGovernorInput = {
  rawConfidence?: number;
  calibratedConfidence?: number;
  requestedExposure?: number;
  maxExposure?: number;
  opensNewExposure?: boolean;
  calibration?: Partial<CalibrationResult> & {
    status?: string;
    explanation?: string;
  };
  judgement?: Partial<JudgementResult> | null;
  reflection?:
    | Partial<ReflectionResult>
    | { reflectionScore?: number; recommendedConfidenceCap?: number }
    | null;
  reliability?: Partial<ReliabilityResult> | null;
  agency?:
    | Partial<AgencyResult>
    | {
        status?: string;
        trust?: number;
        averageTrust?: number;
        blockedActions?: number;
        allowedActions?: number;
      }
    | null;
  belief?: {
    verdict?: string;
    confidence?: number;
    trustworthiness?: number;
    fragility?: number;
    blockers?: string[];
    warnings?: string[];
  } | null;
  strategy?: {
    blocked?: boolean;
    productionEligible?: boolean;
    stage?: string;
    readinessScore?: number;
    maxConfidence?: number;
    maxPositionPct?: number;
    failureFlags?: string[];
  } | null;
  survivalMemory?: TrustSurvivalMemoryInput | null;
  policy?: TrustGovernorPolicy;
};

export type TrustGovernorResult = {
  module: "signal.trust-governor";
  name: "Signal Trust Governor";
  trustScore: number;
  confidenceCap: number;
  participationMode: TrustParticipationMode;
  maxExposure: number;
  allowsNewExposure: boolean;
  requiresReview: boolean;
  allowedActions: TrustGovernorAction[];
  blockedActions: TrustGovernorAction[];
  primaryBlocker?: string;
  blockers: TrustBlocker[];
  unlockCriteria: string[];
  contradictions: string[];
  reasons: string[];
  audit: {
    componentScores: Record<string, number>;
    weights: Record<string, number>;
    rawMaxExposure: number;
    requestedExposure: number;
    survivalRecovery?: {
      status?: string;
      recommendation?: string;
      exposureMultiplier?: number;
      survivalConfidence?: number;
      confidencePenalty?: number;
      maxExposurePct?: number;
      trustedMaxExposure: number;
    };
    formulas: string[];
  };
};

const DEFAULT_POLICY = {
  paperTrustThreshold: 50,
  microTrustThreshold: 62,
  limitedTrustThreshold: 78,
  normalTrustThreshold: 86,
  maxRawCalibratedGap: 15,
  microMaxExposurePct: 1,
  limitedExposureMultiplier: 0.45,
};

const WEIGHTS = {
  calibration: 0.24,
  judgement: 0.18,
  reliability: 0.16,
  reflection: 0.1,
  strategy: 0.11,
  agency: 0.09,
  survival: 0.12,
};

const CALIBRATION_REVIEW_STATUSES = new Set([
  "insufficient-history",
  "insufficient history",
  "poor-calibration",
  "poor calibration",
  "unstable-outcomes",
  "unstable outcomes",
  "overconfident",
]);

const BLOCKING_BELIEF_VERDICTS = new Set(["uncertain", "contradicted"]);

export function evaluateTrustGovernor(input: TrustGovernorInput): TrustGovernorResult {
  const policy = { ...DEFAULT_POLICY, ...(input.policy ?? {}) };
  const rawConfidence = score(input.rawConfidence, score(input.strategy?.maxConfidence, 50));
  const calibratedConfidence = score(
    input.calibratedConfidence ?? input.calibration?.calibratedConfidence,
    rawConfidence,
  );
  const configuredMaxExposure = percent(input.maxExposure ?? input.strategy?.maxPositionPct, 0);
  const rawMaxExposure = survivalAdjustedMaxExposure(input.survivalMemory, configuredMaxExposure);
  const requestedExposure = percent(input.requestedExposure, rawMaxExposure);
  const calibrationStatus = normalizedStatus(input.calibration?.status);
  const calibrationWarnings = normalizedWarnings(input.calibration?.warnings);
  const blockers = collectBlockers({
    input,
    rawConfidence,
    calibratedConfidence,
    rawMaxExposure,
    calibrationStatus,
    calibrationWarnings,
    policy,
  });
  const componentScores = {
    calibration: calibrationScore(input, calibratedConfidence, calibrationStatus, calibrationWarnings),
    judgement: judgementScore(input.judgement),
    reliability: reliabilityScore(input.reliability),
    reflection: reflectionScore(input.reflection),
    strategy: strategyScore(input.strategy),
    agency: agencyScore(input.agency),
    survival: survivalScore(input.survivalMemory),
  };
  const baseTrust = weightedScore(componentScores, WEIGHTS);
  const confidenceCap = confidenceCapFor({
    input,
    rawConfidence,
    calibratedConfidence,
  });
  const trustScore = roundScore(Math.min(baseTrust, confidenceCap));
  const contradictions = contradictionsFor({
    input,
    calibrationStatus,
    calibrationWarnings,
    blockers,
  });
  const participationMode = participationModeFor({
    trustScore,
    confidenceCap,
    rawMaxExposure,
    blockers,
    policy,
  });
  const maxExposure = exposureFor({
    mode: participationMode,
    rawMaxExposure,
    requestedExposure,
    policy,
  });
  const allowsNewExposure = participationMode === "micro" || participationMode === "limited" || participationMode === "normal";
  const requiresReview = blockers.length > 0 || participationMode === "paper" || participationMode === "exits_only";
  const allowedActions = allowedActionsFor(participationMode);
  const blockedActions = blockedActionsFor(participationMode);
  const primaryBlocker = blockers[0]?.id;
  const unlockCriteria = unique(blockers.flatMap((blocker) => blocker.unlockCriteria));

  return {
    module: "signal.trust-governor",
    name: "Signal Trust Governor",
    trustScore,
    confidenceCap,
    participationMode,
    maxExposure,
    allowsNewExposure,
    requiresReview,
    allowedActions,
    blockedActions,
    ...(primaryBlocker ? { primaryBlocker } : {}),
    blockers,
    unlockCriteria,
    contradictions,
    reasons: reasonsFor({
      participationMode,
      trustScore,
      confidenceCap,
      maxExposure,
      blockers,
      contradictions,
    }),
    audit: {
      componentScores,
      weights: WEIGHTS,
      rawMaxExposure,
      requestedExposure,
      formulas: [
        "trustScore = weighted mean of calibration, judgement, reliability, reflection, strategy, and agency scores, capped by trusted confidence",
        "confidenceCap = min(raw confidence, calibrated confidence, reliability cap, reflection cap, and judgement adjusted confidence when present)",
        "survival memory can cap confidence and trusted exposure before participation mode is selected",
        "participationMode = blocked/exits_only/paper/micro/limited/normal based on hard blockers, confidence cap, trust score, survival recovery, and exposure capacity",
      ],
      ...survivalAuditFor(input.survivalMemory, rawMaxExposure),
    },
  };
}

export const governTrust = evaluateTrustGovernor;
export const evaluateSignalTrust = evaluateTrustGovernor;

function collectBlockers(input: {
  input: TrustGovernorInput;
  rawConfidence: number;
  calibratedConfidence: number;
  rawMaxExposure: number;
  calibrationStatus: string;
  calibrationWarnings: string[];
  policy: Required<typeof DEFAULT_POLICY>;
}) {
  const blockers: TrustBlocker[] = [];
  const warnings = input.calibrationWarnings;
  const status = input.calibrationStatus;
  const reliabilityStatus = normalizedStatus(input.input.reliability?.status);
  const reliabilityScoreValue = score(input.input.reliability?.score, 100);
  const reliabilityCap = score(input.input.reliability?.confidenceCap, 100);
  const flags = Array.isArray(input.input.strategy?.failureFlags)
    ? input.input.strategy.failureFlags.filter(Boolean)
    : [];
  const strategyFlagBlockers = blockersForStrategyFlags(flags);
  const gap = input.rawConfidence - input.calibratedConfidence;
  const beliefVerdict = normalizedStatus(input.input.belief?.verdict);
  const agencyStatus = normalizedStatus(input.input.agency?.status);

  if (reliabilityStatus === "invalid" || reliabilityStatus === "stale" || reliabilityScoreValue < 35 || reliabilityCap < 35) {
    blockers.push(blocker(
      "data_reliability_unusable",
      "Data reliability unusable",
      "critical",
      "Market data reliability is too weak to trust new exposure.",
      ["Restore fresh, complete, non-stale market data.", "Raise reliability confidence cap above 35%."],
    ));
  }

  blockers.push(...strategyFlagBlockers);
  blockers.push(...survivalBlockers(input.input.survivalMemory, input.input.opensNewExposure !== false));

  if ((input.input.strategy?.blocked === true || flags.length > 0) && strategyFlagBlockers.length === 0) {
    blockers.push(blocker(
      "strategy_readiness_blocked",
      "Strategy readiness blocked",
      "high",
      "Strategy readiness gates do not allow new exposure.",
      ["Clear readiness failure flags.", "Keep benchmark, drawdown, robustness, and walk-forward checks passing."],
    ));
  }

  if (input.rawMaxExposure <= 0 && input.input.opensNewExposure !== false) {
    blockers.push(blocker(
      "capacity_unavailable",
      "Capacity unavailable",
      "high",
      "No trusted exposure capacity is currently available.",
      ["Restore a positive trusted max exposure cap."],
    ));
  }

  if (status && CALIBRATION_REVIEW_STATUSES.has(status)) {
    blockers.push(calibrationBlockerForStatus(status));
  } else if (warnings.includes("unstable outcomes")) {
    blockers.push(calibrationBlockerForStatus("unstable-outcomes"));
  } else if (warnings.includes("poor calibration") || warnings.includes("overconfidence")) {
    blockers.push(calibrationBlockerForStatus("poor-calibration"));
  }

  if (gap >= input.policy.maxRawCalibratedGap) {
    blockers.push(blocker(
      "raw_calibrated_confidence_gap",
      "Raw/calibrated gap",
      gap >= 25 ? "high" : "medium",
      "Raw confidence is materially higher than calibrated confidence.",
      ["Reduce the raw-vs-calibrated confidence gap below the policy threshold.", "Close more outcomes that match predicted confidence."],
    ));
  }

  if (input.input.judgement?.status === "blocked") {
    blockers.push(blocker(
      "judgement_blocked",
      "Judgement blocked",
      "high",
      "Similar historical states do not justify new exposure.",
      ["Improve similar-state outcome stability.", "Reduce overfit risk in similar historical samples."],
    ));
  } else if (input.input.judgement?.status === "review_required") {
    blockers.push(blocker(
      "judgement_review_required",
      "Judgement requires review",
      "high",
      "Similar historical states require human review before new exposure.",
      ["Raise judgement reliability and outcome stability above review thresholds."],
    ));
  }

  if (BLOCKING_BELIEF_VERDICTS.has(beliefVerdict)) {
    blockers.push(blocker(
      `belief_${beliefVerdict}`,
      "Belief unresolved",
      "high",
      `Belief is ${beliefVerdict}, so new exposure is not justified.`,
      ["Resolve contradictory evidence.", "Raise belief confidence above the justified threshold."],
    ));
  } else if (beliefVerdict === "weak") {
    blockers.push(blocker(
      "belief_weak",
      "Belief weak",
      "medium",
      "Belief is weak and should be reviewed before increasing participation.",
      ["Raise evidence strength, coverage, and agreement enough to justify the claim."],
    ));
  }

  if (["denied", "deferred", "requires-review", "requires_human_review", "escalated"].includes(agencyStatus)) {
    blockers.push(blocker(
      "agency_review_gate",
      "Agency review gate",
      agencyStatus === "denied" ? "high" : "medium",
      "Agency policy does not fully approve commitment.",
      ["Clear agency policy violations.", "Resolve human review requirements."],
    ));
  }

  return uniqueBlockers(blockers);
}

function blockersForStrategyFlags(flags: string[]) {
  const blockers: TrustBlocker[] = [];
  const normalizedFlags = new Set(
    flags.map((flag) =>
      String(flag ?? "")
        .trim()
        .toUpperCase()
        .replace(/[^A-Z0-9]+/g, "_"),
    ),
  );

  if (normalizedFlags.has("ROBUSTNESS_EXECUTION_BLOCKED")) {
    blockers.push(blocker(
      "robustness_execution_blocked",
      "Robustness execution blocked",
      "high",
      "The robustness safety gate blocks new execution.",
      ["Clear the robustness safety gate.", "Keep overfit risk at or below 30%.", "Keep deployment readiness above 60%."],
    ));
  } else if (normalizedFlags.has("ROBUSTNESS_OVERFIT_RISK")) {
    blockers.push(blocker(
      "robustness_overfit_risk",
      "Robustness overfit risk",
      "high",
      "Robustness overfit risk is above the execution threshold.",
      ["Reduce overfit risk to 30% or lower.", "Keep deployment readiness above 60%.", "Retest on independent periods before allowing exposure."],
    ));
  }

  if (normalizedFlags.has("PARAMETER_INSTABILITY")) {
    blockers.push(blocker(
      "parameter_instability",
      "Parameter instability",
      "high",
      "Nearby strategy variants do not preserve the edge.",
      ["Improve parameter pass rate.", "Verify nearby variants still beat the benchmark safety margin."],
    ));
  }

  if (
    normalizedFlags.has("OUTLIER_DEPENDENCY") ||
    normalizedFlags.has("OVERFIT_TOP_WINNER_DEPENDENCY") ||
    normalizedFlags.has("OVERFIT_SEGMENT_CONCENTRATION")
  ) {
    blockers.push(blocker(
      "concentration_dependency",
      "Concentration dependency",
      "high",
      "Results depend too much on a few winners or periods.",
      ["Reduce top-winner and period concentration.", "Confirm median trade return stays positive."],
    ));
  }

  if (normalizedFlags.has("SURVIVAL_NEAR_RUIN")) {
    blockers.push(blocker(
      "survival_near_ruin",
      "Survival near-ruin",
      "high",
      "Survival memory identifies near-ruin patterns; new exposure must wait for recovery evidence.",
      ["Wait until similar states show survival cost below 35/100 and no near-ruin match.", "Restore a positive recovery exposure cap."],
    ));
  }

  return blockers;
}

function calibrationBlockerForStatus(status: string) {
  if (status === "unstable-outcomes" || status === "unstable outcomes") {
    return blocker(
      "calibration_unstable_outcomes",
      "Calibration unstable outcomes",
      "high",
      "Calibration has samples, but similar outcomes are unstable.",
      ["Observe more closed outcomes in similar states.", "Keep outcome stability above the review threshold.", "Reduce overconfidence warnings."],
    );
  }

  if (status === "insufficient-history" || status === "insufficient history") {
    return blocker(
      "calibration_insufficient_history",
      "Calibration insufficient history",
      "high",
      "Calibration history is insufficient for trusted new exposure.",
      ["Collect the minimum number of evaluated outcomes.", "Keep new exposure in paper or review mode until history is usable."],
    );
  }

  return blocker(
    "calibration_poor",
    "Calibration poor",
    "high",
    "Historical calibration does not support trusting the raw signal yet.",
    ["Improve calibration quality.", "Reduce overconfidence warnings.", "Close outcomes that match predicted confidence."],
  );
}

function calibrationScore(
  input: TrustGovernorInput,
  calibratedConfidence: number,
  status: string,
  warnings: string[],
) {
  const trustworthiness = score(input.calibration?.trustworthiness, calibratedConfidence);
  const historicalAccuracy = score(input.calibration?.historicalAccuracy, trustworthiness);
  const calibrationError = Math.abs(Number(input.calibration?.calibrationError ?? 0));
  const quality = clamp(100 - calibrationError);
  let result = mean([calibratedConfidence, trustworthiness, historicalAccuracy, quality]);

  if (status === "unstable-outcomes" || warnings.includes("unstable outcomes")) result -= 18;
  if (status === "poor-calibration" || warnings.includes("poor calibration")) result -= 14;
  if (status === "insufficient-history" || warnings.includes("insufficient history")) result -= 12;
  if (warnings.includes("overconfidence")) result -= 8;
  if (warnings.includes("low trustworthiness")) result -= 10;

  return roundScore(result);
}

function judgementScore(judgement: TrustGovernorInput["judgement"]) {
  if (!judgement) return 60;
  const trust = score(judgement.trust, score(judgement.adjustedConfidence, 50));
  const reliability = score(judgement.reliability, trust);
  const stability = score(judgement.outcomeStability, trust);
  const calibration = score(judgement.calibration, trust);
  const overfitSafety = clamp(100 - score(judgement.overfitRisk, 50));
  let result = mean([trust, reliability, stability, calibration, overfitSafety]);

  if (judgement.status === "blocked") result = Math.min(result, 20);
  if (judgement.status === "review_required") result = Math.min(result, 45);
  if (judgement.status === "cautious") result = Math.min(result, 70);

  return roundScore(result);
}

function reliabilityScore(reliability: TrustGovernorInput["reliability"]) {
  if (!reliability) return 75;
  const status = normalizedStatus(reliability.status);
  let result = mean([
    score(reliability.score, 75),
    score(reliability.confidenceCap, 75),
  ]);

  if (status === "invalid") result = Math.min(result, 10);
  if (status === "stale") result = Math.min(result, 25);
  if (status === "insufficient") result = Math.min(result, 45);
  if (status === "degraded") result = Math.min(result, 65);

  return roundScore(result);
}

function reflectionScore(reflection: TrustGovernorInput["reflection"]) {
  if (!reflection) return 65;
  return score(reflection.reflectionScore, 65);
}

function strategyScore(strategy: TrustGovernorInput["strategy"]) {
  if (!strategy) return 65;
  let result = mean([
    score(strategy.readinessScore, score(strategy.maxConfidence, 60)),
    score(strategy.maxConfidence, score(strategy.readinessScore, 60)),
  ]);

  if (strategy.blocked === true) result = Math.min(result, 30);
  if (strategy.productionEligible === false) result = Math.min(result, 72);

  return roundScore(result);
}

function agencyScore(agency: TrustGovernorInput["agency"]) {
  if (!agency) return 65;
  const status = normalizedStatus(agency.status);
  const trust = score(
    (agency as { trust?: number }).trust ??
      (agency as { averageTrust?: number }).averageTrust ??
      (agency as Partial<AgencyResult>).commitmentConfidence ??
      (agency as Partial<AgencyResult>).agencyScore,
    65,
  );
  let result = trust;

  if (status === "denied") result = Math.min(result, 20);
  if (status === "deferred") result = Math.min(result, 45);
  if (status === "requires-review" || status === "requires_human_review" || status === "escalated") {
    result = Math.min(result, 55);
  }
  if (status === "limited") result = Math.min(result, 72);

  return roundScore(result);
}

function survivalScore(survivalMemory: TrustGovernorInput["survivalMemory"]) {
  if (!survivalMemory) return 75;

  const status = normalizedStatus(survivalMemory.status);
  const recommendation = normalizedStatus(survivalMemory.recommendation);
  const confidence = score(survivalMemory.survivalConfidence, status === "empty" ? 75 : 70);
  const multiplierScore = ratioScore(survivalMemory.exposureMultiplier, 1) * 100;
  const costSafety = clamp(100 - score(survivalMemory.averageSurvivalCost, 0));
  const penaltySafety = clamp(100 - score(survivalMemory.confidencePenalty, 0));
  let result = mean([confidence, multiplierScore, costSafety, penaltySafety]);

  if (recommendation === "wait" || status === "near-ruin") result = Math.min(result, 35);
  if (recommendation === "act-with-reduced-size") result = Math.min(result, 65);
  if (status === "scarred") result = Math.min(result, 60);
  if (status === "watch") result = Math.min(result, 75);

  return roundScore(result);
}

function confidenceCapFor(input: {
  input: TrustGovernorInput;
  rawConfidence: number;
  calibratedConfidence: number;
}) {
  const caps = [
    input.rawConfidence,
    input.calibratedConfidence,
    score(input.input.reliability?.confidenceCap, 100),
    score((input.input.reflection as { recommendedConfidenceCap?: number } | null | undefined)?.recommendedConfidenceCap, 100),
  ];

  if (input.input.judgement?.adjustedConfidence != null) {
    caps.push(score(input.input.judgement.adjustedConfidence, 100));
  }

  if (input.input.strategy?.maxConfidence != null) {
    caps.push(score(input.input.strategy.maxConfidence, 100));
  }

  if (input.input.belief?.confidence != null) {
    caps.push(score(input.input.belief.confidence, 100));
  }

  if (input.input.belief?.trustworthiness != null) {
    caps.push(score(input.input.belief.trustworthiness, 100));
  }

  if (input.input.survivalMemory?.survivalConfidence != null) {
    caps.push(score(input.input.survivalMemory.survivalConfidence, 100));
  }

  if (input.input.survivalMemory?.confidencePenalty != null) {
    caps.push(clamp(100 - score(input.input.survivalMemory.confidencePenalty, 0)));
  }

  return roundScore(Math.min(...caps.filter(Number.isFinite)));
}

function survivalBlockers(survivalMemory: TrustGovernorInput["survivalMemory"], opensNewExposure: boolean): TrustBlocker[] {
  if (!survivalMemory || !opensNewExposure) return [];

  const status = normalizedStatus(survivalMemory.status);
  const recommendation = normalizedStatus(survivalMemory.recommendation);
  const nearRuinCount = finiteNumber(survivalMemory.nearRuinCount) ?? 0;
  const scarCount = finiteNumber(survivalMemory.scarCount) ?? 0;
  const exposureMultiplier = ratioScore(survivalMemory.exposureMultiplier, 1);
  const unlockCriteria = Array.isArray(survivalMemory.unlockConditions) && survivalMemory.unlockConditions.length
    ? survivalMemory.unlockConditions
    : ["Wait until similar states show survival cost below 35/100 and no near-ruin match.", "Restore a positive recovery exposure cap."];

  if (recommendation === "wait" || status === "near-ruin" || nearRuinCount > 0 && exposureMultiplier <= 0.2 || exposureMultiplier === 0) {
    return [blocker(
      "survival_memory_wait",
      "Survival memory wait",
      "high",
      "Survival memory blocks new exposure until recovery evidence clears the near-ruin pattern.",
      unlockCriteria,
    )];
  }

  if (recommendation === "act-with-reduced-size" || scarCount > 0 || exposureMultiplier < 0.85) {
    return [blocker(
      "survival_reduced_size",
      "Survival reduced size",
      "medium",
      "Survival memory allows only reduced-size recovery exposure.",
      Array.isArray(survivalMemory.unlockConditions) && survivalMemory.unlockConditions.length
        ? survivalMemory.unlockConditions
        : ["Raise survival confidence above 70/100 before normal sizing is restored."],
    )];
  }

  return [];
}

function participationModeFor(input: {
  trustScore: number;
  confidenceCap: number;
  rawMaxExposure: number;
  blockers: TrustBlocker[];
  policy: Required<typeof DEFAULT_POLICY>;
}): TrustParticipationMode {
  const critical = input.blockers.some((blocker) => blocker.severity === "critical");
  const hard = input.blockers.some((blocker) => blocker.severity === "high");

  if (critical) return "blocked";
  if (hard) return "exits_only";
  if (input.rawMaxExposure <= 0) return "exits_only";
  if (input.trustScore < input.policy.paperTrustThreshold || input.confidenceCap < input.policy.paperTrustThreshold) {
    return "paper";
  }
  if (input.trustScore < input.policy.microTrustThreshold) return "micro";
  if (input.trustScore < input.policy.limitedTrustThreshold) return "limited";
  if (input.trustScore < input.policy.normalTrustThreshold) return "limited";
  return "normal";
}

function exposureFor(input: {
  mode: TrustParticipationMode;
  rawMaxExposure: number;
  requestedExposure: number;
  policy: Required<typeof DEFAULT_POLICY>;
}) {
  if (input.mode === "blocked" || input.mode === "exits_only" || input.mode === "paper") return 0;
  if (input.mode === "micro") return roundExposure(Math.min(input.rawMaxExposure, input.policy.microMaxExposurePct));
  if (input.mode === "limited") {
    return roundExposure(Math.min(input.rawMaxExposure, Math.max(input.policy.microMaxExposurePct, input.rawMaxExposure * input.policy.limitedExposureMultiplier)));
  }
  return roundExposure(input.rawMaxExposure);
}

function survivalAdjustedMaxExposure(
  survivalMemory: TrustGovernorInput["survivalMemory"],
  configuredMaxExposure: number,
) {
  if (!survivalMemory) return configuredMaxExposure;

  const caps = [configuredMaxExposure];
  const maxExposurePct = finiteNumber(survivalMemory.maxExposurePct);
  const exposureMultiplier = ratioScore(survivalMemory.exposureMultiplier, 1);
  const recommendation = normalizedStatus(survivalMemory.recommendation);

  if (maxExposurePct != null) caps.push(Math.max(0, maxExposurePct));
  if (maxExposurePct == null && exposureMultiplier < 1) caps.push(configuredMaxExposure * exposureMultiplier);
  if (recommendation === "wait") caps.push(0);

  return roundExposure(Math.min(...caps));
}

function survivalAuditFor(
  survivalMemory: TrustGovernorInput["survivalMemory"],
  trustedMaxExposure: number,
) {
  if (!survivalMemory) return {};

  return {
    survivalRecovery: {
      ...(survivalMemory.status == null ? {} : { status: String(survivalMemory.status) }),
      ...(survivalMemory.recommendation == null ? {} : { recommendation: String(survivalMemory.recommendation) }),
      ...(survivalMemory.exposureMultiplier == null ? {} : { exposureMultiplier: ratioScore(survivalMemory.exposureMultiplier, 1) }),
      ...(survivalMemory.survivalConfidence == null ? {} : { survivalConfidence: score(survivalMemory.survivalConfidence, 0) }),
      ...(survivalMemory.confidencePenalty == null ? {} : { confidencePenalty: score(survivalMemory.confidencePenalty, 0) }),
      ...(survivalMemory.maxExposurePct == null ? {} : { maxExposurePct: percent(survivalMemory.maxExposurePct, 0) }),
      trustedMaxExposure,
    },
  };
}

function allowedActionsFor(mode: TrustParticipationMode): TrustGovernorAction[] {
  if (mode === "blocked") return ["observe"];
  if (mode === "exits_only") return ["observe", "risk_reducing_exits"];
  if (mode === "paper") return ["observe", "paper_trade", "risk_reducing_exits"];
  return ["observe", "paper_trade", "risk_reducing_exits", "new_exposure", "increase_position"];
}

function blockedActionsFor(mode: TrustParticipationMode): TrustGovernorAction[] {
  if (mode === "normal" || mode === "limited" || mode === "micro") return [];
  if (mode === "paper") return ["new_exposure", "increase_position"];
  if (mode === "exits_only") return ["paper_trade", "new_exposure", "increase_position"];
  return ["paper_trade", "risk_reducing_exits", "new_exposure", "increase_position"];
}

function contradictionsFor(input: {
  input: TrustGovernorInput;
  calibrationStatus: string;
  calibrationWarnings: string[];
  blockers: TrustBlocker[];
}) {
  const contradictions: string[] = [];
  const calibrationBlocked =
    CALIBRATION_REVIEW_STATUSES.has(input.calibrationStatus) ||
    input.calibrationWarnings.includes("unstable outcomes") ||
    input.calibrationWarnings.includes("poor calibration");
  const judgementStatus = input.input.judgement?.status;
  const reliabilityStatus = normalizedStatus(input.input.reliability?.status);
  const agencyStatus = normalizedStatus(input.input.agency?.status);

  if ((judgementStatus === "trusted" || judgementStatus === "cautious") && calibrationBlocked) {
    contradictions.push("Judgement finds similar history usable, but calibration still requires review.");
  }
  if (input.input.strategy?.productionEligible === true && input.blockers.length > 0) {
    contradictions.push("Backtest readiness is production-eligible, but trust gates still block live participation.");
  }
  if ((reliabilityStatus === "healthy" || reliabilityStatus === "") && input.blockers.some((blocker) => blocker.id.startsWith("calibration_"))) {
    contradictions.push("Market data is reliable, but model calibration is not stable enough for new exposure.");
  }
  if ((agencyStatus === "approved" || agencyStatus === "act") && input.blockers.length > 0) {
    contradictions.push("Agency approval conflicts with unresolved trust blockers.");
  }

  return unique(contradictions);
}

function reasonsFor(input: {
  participationMode: TrustParticipationMode;
  trustScore: number;
  confidenceCap: number;
  maxExposure: number;
  blockers: TrustBlocker[];
  contradictions: string[];
}) {
  const reasons = [
    `Signal Trust Governor selected ${input.participationMode.replace(/_/g, " ")} mode with trust ${formatPercent(input.trustScore)} and confidence cap ${formatPercent(input.confidenceCap)}.`,
  ];

  if (input.blockers.length) {
    reasons.push(input.blockers[0].reason);
  } else if (input.maxExposure > 0) {
    reasons.push(`Trusted maximum exposure is ${formatExposure(input.maxExposure)}.`);
  }

  if (input.contradictions.length) {
    reasons.push(input.contradictions[0]);
  }

  return unique(reasons);
}

function blocker(
  id: string,
  label: string,
  severity: TrustBlockerSeverity,
  reason: string,
  unlockCriteria: string[],
): TrustBlocker {
  return {
    id,
    label,
    severity,
    reason,
    unlockCriteria,
  };
}

function weightedScore(scores: Record<string, number>, weights: Record<string, number>) {
  const totalWeight = Object.values(weights).reduce((sum, value) => sum + value, 0);
  const weighted = Object.entries(weights).reduce(
    (sum, [key, weight]) => sum + score(scores[key], 0) * weight,
    0,
  );
  return roundScore(totalWeight > 0 ? weighted / totalWeight : 0);
}

function score(value: unknown, fallback: number) {
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) return clamp(fallback);
  return roundScore(Math.abs(numberValue) <= 1 ? numberValue * 100 : numberValue);
}

function ratioScore(value: unknown, fallback: number) {
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) return Math.min(1, Math.max(0, fallback));
  return Math.min(1, Math.max(0, numberValue));
}

function finiteNumber(value: unknown) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : undefined;
}

function percent(value: unknown, fallback: number) {
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) return Math.max(0, fallback);
  return roundExposure(Math.max(0, numberValue));
}

function normalizedStatus(value: unknown) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/[_\s]+/g, "-");
}

function normalizedWarnings(value: unknown) {
  return Array.isArray(value)
    ? value.map((item) => String(item ?? "").trim().toLowerCase()).filter(Boolean)
    : [];
}

function unique(values: string[]) {
  return Array.from(new Set(values.filter(Boolean)));
}

function uniqueBlockers(blockers: TrustBlocker[]) {
  const byId = new Map<string, TrustBlocker>();

  for (const blocker of blockers) {
    if (!byId.has(blocker.id)) byId.set(blocker.id, blocker);
  }

  return Array.from(byId.values()).sort((left, right) => severityRank(right.severity) - severityRank(left.severity));
}

function severityRank(severity: TrustBlockerSeverity) {
  if (severity === "critical") return 4;
  if (severity === "high") return 3;
  if (severity === "medium") return 2;
  return 1;
}

function roundScore(value: number) {
  return Math.round(clamp(value) * 100) / 100;
}

function roundExposure(value: number) {
  return Math.round(Math.max(0, value) * 100) / 100;
}

function formatPercent(value: number) {
  return `${Math.round(value)}%`;
}

function formatExposure(value: number) {
  return `${roundExposure(value).toFixed(2)}%`;
}

import { clamp, mean } from "../math/statistics";

export type BeliefVerdict = "justified" | "weak" | "contradicted" | "uncertain";

export type EvidenceDirection = "support" | "contradict" | "neutral";

export interface EvidenceInput {
  name: string;
  direction: EvidenceDirection;
  strength: number;
  confidence?: number;
  weight?: number;
  source?: string;
  reason?: string;
  metadata?: Record<string, unknown>;
}

export interface EvidenceResult {
  name: string;
  direction: EvidenceDirection;
  strength: number;
  confidence: number;
  weight: number;
  weightedStrength: number;
  source?: string;
  reason: string;
  metadata?: Record<string, unknown>;
}

export interface BeliefInput {
  claim: string;
  priorConfidence?: number;
  evidence: EvidenceInput[];
  uncertainty?: number;
  minimumEvidenceCount?: number;
  minimumCoverage?: number;
  contradictionTolerance?: number;
  metadata?: Record<string, unknown>;
}

export interface BeliefResult {
  claim: string;
  verdict: BeliefVerdict;
  confidence: number;
  trustworthiness: number;
  evidenceStrength: number;
  evidenceAgreement: number;
  evidenceCoverage: number;
  supportStrength: number;
  contradictionStrength: number;
  uncertainty: number;
  fragility: number;
  supportingEvidence: EvidenceResult[];
  contradictoryEvidence: EvidenceResult[];
  neutralEvidence: EvidenceResult[];
  blockers: string[];
  warnings: string[];
  reason: string;
  audit: {
    formula: string;
    inputs: BeliefInput;
    normalized: Record<string, number>;
    steps: string[];
  };
}

type BeliefMetrics = {
  priorConfidence: number;
  uncertainty: number;
  minimumEvidenceCount: number;
  minimumCoverage: number;
  contradictionTolerance: number;
  evidenceStrength: number;
  evidenceAgreement: number;
  evidenceCoverage: number;
  supportStrength: number;
  contradictionStrength: number;
  neutralStrength: number;
  averageEvidenceConfidence: number;
  sourceDominance: number;
  confidence: number;
  trustworthiness: number;
  fragility: number;
};

const DEFAULT_PRIOR_CONFIDENCE = 50;
const DEFAULT_EVIDENCE_CONFIDENCE = 50;
const DEFAULT_EVIDENCE_WEIGHT = 1;
const DEFAULT_UNCERTAINTY = 0;
const DEFAULT_MINIMUM_EVIDENCE_COUNT = 3;
const DEFAULT_MINIMUM_COVERAGE = 60;
const DEFAULT_CONTRADICTION_TOLERANCE = 35;

export function evaluateBelief(input: BeliefInput): BeliefResult {
  const evidence = safeEvidence(input.evidence).map(evaluateEvidence);
  const supportingEvidence = evidenceByDirection(evidence, "support");
  const contradictoryEvidence = evidenceByDirection(evidence, "contradict");
  const neutralEvidence = evidenceByDirection(evidence, "neutral");
  const metrics = calculateBeliefMetrics(input, evidence);
  const warnings = collectWarnings(metrics, evidence);
  const verdict = resolveVerdict(metrics, evidence);
  const blockers = collectBlockers(verdict, metrics, evidence);
  const result: BeliefResult = {
    claim: String(input.claim ?? "").trim() || "Unspecified claim",
    verdict,
    confidence: metrics.confidence,
    trustworthiness: metrics.trustworthiness,
    evidenceStrength: metrics.evidenceStrength,
    evidenceAgreement: metrics.evidenceAgreement,
    evidenceCoverage: metrics.evidenceCoverage,
    supportStrength: metrics.supportStrength,
    contradictionStrength: metrics.contradictionStrength,
    uncertainty: metrics.uncertainty,
    fragility: metrics.fragility,
    supportingEvidence,
    contradictoryEvidence,
    neutralEvidence,
    blockers,
    warnings,
    reason: "",
    audit: {
      formula:
        "confidence = prior*0.25 + support*0.8 - contradiction*0.65 - uncertainty*0.3 + (coverage-50)*0.15 + (agreement-50)*0.1; trustworthiness = agreement*0.25 + coverage*0.25 + averageEvidenceConfidence*0.35 + (100-uncertainty)*0.15; fragility = lowCoverage*0.4 + conflict*0.2 + uncertainty*0.2 + lowEvidenceConfidence*0.1 + sourceDominance*0.1",
      inputs: {
        ...input,
        claim: String(input.claim ?? ""),
        evidence: safeEvidence(input.evidence),
      },
      normalized: normalizedAudit(metrics),
      steps: [
        `Evaluated ${evidence.length} evidence item(s).`,
        `Support ${formatScore(metrics.supportStrength)} vs contradiction ${formatScore(metrics.contradictionStrength)}.`,
        `Coverage ${formatScore(metrics.evidenceCoverage)}, agreement ${formatScore(metrics.evidenceAgreement)}, uncertainty ${formatScore(metrics.uncertainty)}.`,
        `Confidence ${formatScore(metrics.confidence)}, trustworthiness ${formatScore(metrics.trustworthiness)}, fragility ${formatScore(metrics.fragility)}.`,
      ],
    },
  };

  return {
    ...result,
    reason: createBeliefReason(result),
  };
}

export function evaluateEvidence(input: EvidenceInput): EvidenceResult {
  const name = String(input.name ?? "").trim() || "evidence";
  const direction = normalizeDirection(input.direction);
  const strength = score(input.strength);
  const confidence = score(input.confidence, DEFAULT_EVIDENCE_CONFIDENCE);
  const weight = score(input.weight, DEFAULT_EVIDENCE_WEIGHT);
  const weightedStrength = roundScore(strength * (confidence / 100) * weight);
  const reason = String(input.reason ?? "").trim() || defaultEvidenceReason(name, direction, strength);

  return {
    name,
    direction,
    strength,
    confidence,
    weight,
    weightedStrength,
    ...(input.source ? { source: String(input.source) } : {}),
    reason,
    ...(input.metadata ? { metadata: input.metadata } : {}),
  };
}

export function calculateEvidenceAgreement(results: EvidenceResult[]): number {
  const evidence = Array.isArray(results) ? results : [];
  if (!evidence.length) return 0;

  const support = directionalStrength(evidence, "support");
  const contradiction = directionalStrength(evidence, "contradict");
  const directionalTotal = support + contradiction;

  if (directionalTotal <= 0) return 50;

  return roundScore((Math.max(support, contradiction) / directionalTotal) * 100);
}

export function calculateBeliefFragility(
  input: BeliefInput,
  evidence: EvidenceResult[],
): number {
  return calculateBeliefMetrics(input, Array.isArray(evidence) ? evidence : []).fragility;
}

export function createBeliefReason(result: BeliefResult): string {
  const support = topEvidenceName(result.supportingEvidence);
  const contradiction = topEvidenceName(result.contradictoryEvidence);
  const suffix = result.blockers.length
    ? ` Blockers: ${result.blockers.join("; ")}.`
    : result.warnings.length
      ? ` Warnings: ${result.warnings.slice(0, 2).join("; ")}.`
      : "";
  const evidencePhrase = [
    support ? `top support: ${support}` : "",
    contradiction ? `top contradiction: ${contradiction}` : "",
  ].filter(Boolean).join("; ");

  return [
    `Belief is ${result.verdict} for "${result.claim}"`,
    `with confidence ${formatScore(result.confidence)}, trustworthiness ${formatScore(result.trustworthiness)}, and fragility ${formatScore(result.fragility)}.`,
    evidencePhrase ? `Evidence ${evidencePhrase}.` : "No directional evidence is available.",
    suffix.trim(),
  ].filter(Boolean).join(" ");
}

function calculateBeliefMetrics(input: BeliefInput, evidence: EvidenceResult[]): BeliefMetrics {
  const priorConfidence = score(input.priorConfidence, DEFAULT_PRIOR_CONFIDENCE);
  const uncertainty = score(input.uncertainty, DEFAULT_UNCERTAINTY);
  const minimumEvidenceCount = Math.max(
    1,
    Math.round(score(input.minimumEvidenceCount, DEFAULT_MINIMUM_EVIDENCE_COUNT)),
  );
  const minimumCoverage = score(input.minimumCoverage, DEFAULT_MINIMUM_COVERAGE);
  const contradictionTolerance = score(
    input.contradictionTolerance,
    DEFAULT_CONTRADICTION_TOLERANCE,
  );
  const supportStrength = directionalStrength(evidence, "support");
  const contradictionStrength = directionalStrength(evidence, "contradict");
  const neutralStrength = directionalStrength(evidence, "neutral");
  const evidenceAgreement = calculateEvidenceAgreement(evidence);
  const averageEvidenceConfidence = roundScore(mean(evidence.map((item) => item.confidence)));
  const evidenceStrength = roundScore(
    Math.max(supportStrength, contradictionStrength, neutralStrength),
  );
  const evidenceCoverage = evidenceCoverageScore(
    evidence.length,
    minimumEvidenceCount,
    averageEvidenceConfidence,
  );
  const sourceDominance = sourceDominanceScore(evidence);
  const confidence = roundScore(
    priorConfidence * 0.25 +
      supportStrength * 0.8 -
      contradictionStrength * 0.65 -
      uncertainty * 0.3 +
      (evidenceCoverage - 50) * 0.15 +
      (evidenceAgreement - 50) * 0.1,
  );
  const trustworthiness = roundScore(
    evidenceAgreement * 0.25 +
      evidenceCoverage * 0.25 +
      averageEvidenceConfidence * 0.35 +
      (100 - uncertainty) * 0.15,
  );
  const conflictFragility =
    supportStrength + contradictionStrength <= 0
      ? 80
      : clamp(100 - Math.abs(supportStrength - contradictionStrength) * 2);
  const dominanceFragility = clamp(Math.max(0, sourceDominance - 50) * 2);
  const fragility = evidence.length
    ? roundScore(
        (100 - evidenceCoverage) * 0.4 +
          conflictFragility * 0.2 +
          uncertainty * 0.2 +
          (100 - averageEvidenceConfidence) * 0.1 +
          dominanceFragility * 0.1,
      )
    : 100;

  return {
    priorConfidence,
    uncertainty,
    minimumEvidenceCount,
    minimumCoverage,
    contradictionTolerance,
    evidenceStrength,
    evidenceAgreement,
    evidenceCoverage,
    supportStrength,
    contradictionStrength,
    neutralStrength,
    averageEvidenceConfidence,
    sourceDominance,
    confidence: clamp(confidence),
    trustworthiness: clamp(trustworthiness),
    fragility: clamp(fragility),
  };
}

function resolveVerdict(metrics: BeliefMetrics, evidence: EvidenceResult[]): BeliefVerdict {
  if (!evidence.length) return "uncertain";

  if (
    metrics.confidence >= 70 &&
    metrics.trustworthiness >= 70 &&
    metrics.contradictionStrength <= metrics.contradictionTolerance &&
    metrics.fragility <= 35 &&
    metrics.evidenceCoverage >= metrics.minimumCoverage
  ) {
    return "justified";
  }

  if (
    metrics.contradictionStrength > metrics.supportStrength ||
    metrics.contradictionStrength >= 60
  ) {
    return "contradicted";
  }

  if (
    metrics.confidence >= 55 &&
    metrics.trustworthiness >= 50 &&
    metrics.contradictionStrength <= 45
  ) {
    return "weak";
  }

  return "uncertain";
}

function collectWarnings(metrics: BeliefMetrics, evidence: EvidenceResult[]) {
  const warnings: string[] = [];

  if (evidence.length > 0 && evidence.length < metrics.minimumEvidenceCount) {
    warnings.push(
      `Evidence count ${evidence.length} is below minimum ${metrics.minimumEvidenceCount}.`,
    );
  }

  if (evidence.length > 0 && metrics.evidenceCoverage < metrics.minimumCoverage) {
    warnings.push(
      `Evidence coverage ${formatScore(metrics.evidenceCoverage)} is below minimum ${formatScore(metrics.minimumCoverage)}.`,
    );
  }

  if (metrics.uncertainty >= 60) {
    warnings.push(`Uncertainty is high at ${formatScore(metrics.uncertainty)}.`);
  }

  if (evidence.length > 0 && metrics.averageEvidenceConfidence < 50) {
    warnings.push(
      `Average evidence confidence is low at ${formatScore(metrics.averageEvidenceConfidence)}.`,
    );
  }

  if (metrics.sourceDominance >= 70) {
    warnings.push(`One evidence source dominates ${formatScore(metrics.sourceDominance)} of source weight.`);
  }

  if (
    metrics.supportStrength > 0 &&
    metrics.contradictionStrength > 0 &&
    Math.abs(metrics.supportStrength - metrics.contradictionStrength) <= 15
  ) {
    warnings.push("Supporting and contradictory evidence are close.");
  }

  if (metrics.contradictionStrength > metrics.contradictionTolerance) {
    warnings.push(
      `Contradiction ${formatScore(metrics.contradictionStrength)} exceeds tolerance ${formatScore(metrics.contradictionTolerance)}.`,
    );
  }

  return unique(warnings);
}

function collectBlockers(
  verdict: BeliefVerdict,
  metrics: BeliefMetrics,
  evidence: EvidenceResult[],
) {
  if (verdict === "justified" || verdict === "weak") return [];

  const blockers: string[] = [];

  if (!evidence.length) {
    blockers.push("No evidence was supplied.");
  }

  if (
    verdict === "contradicted" &&
    metrics.contradictionStrength > metrics.supportStrength
  ) {
    blockers.push("Contradictory evidence is stronger than supporting evidence.");
  }

  if (metrics.contradictionStrength >= 60) {
    blockers.push("Contradictory evidence is strong.");
  }

  if (evidence.length > 0 && metrics.confidence < 55) {
    blockers.push(`Confidence ${formatScore(metrics.confidence)} is below weak-belief threshold.`);
  }

  if (evidence.length > 0 && metrics.trustworthiness < 50) {
    blockers.push(`Trustworthiness ${formatScore(metrics.trustworthiness)} is below minimum.`);
  }

  if (evidence.length > 0 && metrics.evidenceCoverage < metrics.minimumCoverage) {
    blockers.push("Evidence coverage is insufficient.");
  }

  if (evidence.length > 0 && metrics.fragility > 65) {
    blockers.push("Belief is too fragile.");
  }

  return unique(blockers);
}

function evidenceByDirection(evidence: EvidenceResult[], direction: EvidenceDirection) {
  return evidence
    .filter((item) => item.direction === direction)
    .sort((a, b) => b.weightedStrength - a.weightedStrength || a.name.localeCompare(b.name));
}

function directionalStrength(evidence: EvidenceResult[], direction: EvidenceDirection) {
  const directional = evidence.filter((item) => item.direction === direction);
  const totalWeight = directional.reduce((sum, item) => sum + item.weight, 0);
  if (totalWeight <= 0) return 0;

  return roundScore(
    directional.reduce((sum, item) => sum + item.weightedStrength, 0) / totalWeight,
  );
}

function evidenceCoverageScore(
  evidenceCount: number,
  minimumEvidenceCount: number,
  averageEvidenceConfidence: number,
) {
  if (evidenceCount <= 0) return 0;

  const countCoverage = clamp((evidenceCount / minimumEvidenceCount) * 100);
  return roundScore(countCoverage * 0.85 + averageEvidenceConfidence * 0.15);
}

function sourceDominanceScore(evidence: EvidenceResult[]) {
  const sourceWeights = new Map<string, number>();
  let totalWeight = 0;

  for (const item of evidence) {
    const sourceKey = String(item.source ?? `evidence:${item.name}`);
    const sourceWeight = item.weight * (item.confidence / 100);
    sourceWeights.set(sourceKey, (sourceWeights.get(sourceKey) ?? 0) + sourceWeight);
    totalWeight += sourceWeight;
  }

  if (totalWeight <= 0 || sourceWeights.size === 0) return 0;

  return roundScore((Math.max(...sourceWeights.values()) / totalWeight) * 100);
}

function normalizedAudit(metrics: BeliefMetrics): Record<string, number> {
  return {
    priorConfidence: metrics.priorConfidence,
    uncertainty: metrics.uncertainty,
    minimumEvidenceCount: metrics.minimumEvidenceCount,
    minimumCoverage: metrics.minimumCoverage,
    contradictionTolerance: metrics.contradictionTolerance,
    evidenceStrength: metrics.evidenceStrength,
    evidenceAgreement: metrics.evidenceAgreement,
    evidenceCoverage: metrics.evidenceCoverage,
    supportStrength: metrics.supportStrength,
    contradictionStrength: metrics.contradictionStrength,
    neutralStrength: metrics.neutralStrength,
    averageEvidenceConfidence: metrics.averageEvidenceConfidence,
    sourceDominance: metrics.sourceDominance,
    confidence: metrics.confidence,
    trustworthiness: metrics.trustworthiness,
    fragility: metrics.fragility,
  };
}

function topEvidenceName(evidence: EvidenceResult[]) {
  const top = evidence[0];
  return top ? `${top.name} (${formatScore(top.weightedStrength)})` : "";
}

function defaultEvidenceReason(name: string, direction: EvidenceDirection, strength: number) {
  return `${name} provides ${direction} evidence with strength ${formatScore(strength)}.`;
}

function safeEvidence(evidence: EvidenceInput[] | undefined) {
  return Array.isArray(evidence) ? evidence : [];
}

function normalizeDirection(direction: EvidenceDirection): EvidenceDirection {
  if (direction === "support" || direction === "contradict" || direction === "neutral") {
    return direction;
  }

  return "neutral";
}

function score(value: unknown, fallback = 0) {
  const numberValue = Number(value);
  return clamp(Number.isFinite(numberValue) ? numberValue : fallback);
}

function roundScore(value: number) {
  return Number(clamp(value).toFixed(2));
}

function formatScore(value: number) {
  return `${Number(value.toFixed(2))}/100`;
}

function unique(values: string[]) {
  return Array.from(new Set(values));
}

/* c8 ignore next */
import { clamp, mean, numeric } from "../math/statistics";
import type { DetectedNeed } from "../types";
import { sizeDecision, type SizingConstraint, type SizingInput, type SizingResult } from "./engine";

export const ADAPTIVE_SIZING_LADDER = [0, 1, 2, 5, 10, 15, 25, 50, 100] as const;

export type AdaptiveSizingInput = {
  targetRef: string;
  actionRef?: string;
  decisionRef?: string;
  opportunityQuality: number;
  signalConfidence: number;
  marketParticipation: number;
  riskControl: number;
  perceptionAlignment: number;
  systemTrust: number;
  discoveryStrength: number;
  risk?: number;
  requestedCapacity?: number;
  availableCapacity?: number;
  minCapacity?: number;
  maxCapacity?: number;
  needs?: DetectedNeed[];
  constraints?: SizingConstraint[];
  ladder?: readonly number[];
  context?: Record<string, unknown>;
};

export type AdaptiveSizingResult = SizingResult & {
  selectedLadderPct: number;
  ladder: number[];
  sizingRationale: string[];
};

/**
 * Adaptive sizing wraps the generic risk gate with an explainable ladder.
 *
 * The base `sizeDecision` remains responsible for hard constraints, caps, and
 * risk normalization. This adapter only chooses the largest graduated step that
 * fits inside the allowed capacity, keeping exploratory allocations possible
 * without bypassing existing safety checks.
 */
export function sizeAdaptiveOpportunity(input: AdaptiveSizingInput): AdaptiveSizingResult {
  const ladder = normalizeLadder(input.ladder ?? ADAPTIVE_SIZING_LADDER);
  const quality = ratio(input.opportunityQuality);
  const confidence = ratio(input.signalConfidence);
  const participation = ratio(input.marketParticipation);
  const riskControl = ratio(input.riskControl);
  const alignment = ratio(input.perceptionAlignment);
  const trust = ratio(input.systemTrust);
  const discovery = ratio(input.discoveryStrength);
  const needRisk = needRiskPressure(input.needs ?? []);
  const risk = Math.max(ratio(input.risk ?? 1 - riskControl), 1 - riskControl, needRisk);
  const blendedConfidence = mean([quality, confidence, alignment, trust, discovery]);
  const utility = mean([quality, participation, discovery, needParticipationBoost(input.needs ?? [])]);
  const constraints = [...(input.constraints ?? []), ...constraintsFromNeeds(input.needs ?? [])];
  const baseInput: SizingInput = {
    targetRef: input.targetRef,
    actionRef: input.actionRef,
    decisionRef: input.decisionRef,
    confidence: blendedConfidence,
    risk,
    utility,
    requestedCapacity: input.requestedCapacity,
    availableCapacity: input.availableCapacity,
    minCapacity: input.minCapacity,
    maxCapacity: input.maxCapacity,
    constraints,
    context: input.context,
  };
  const base = sizeDecision(baseInput);
  const allowedCapacity = base.decision === "allowed" ? base.size : 0;
  const selectedLadderPct = selectLadderStep(ladder, allowedCapacity);
  const finalSize = selectedLadderPct;
  /* c8 ignore next */
  const normalizedSize = normalizeByCapacity(finalSize, input.maxCapacity ?? input.availableCapacity ?? input.requestedCapacity);
  const sizingRationale = [
    `Opportunity quality ${formatPct(quality)} and discovery strength ${formatPct(discovery)} set the opportunity tier.`,
    `Signal confidence ${formatPct(confidence)}, alignment ${formatPct(alignment)}, and system trust ${formatPct(trust)} set the confidence tier.`,
    `Risk control ${formatPct(riskControl)} and detected needs keep the final step inside existing safety gates.`,
    `Selected ladder step ${formatNumber(selectedLadderPct)} from ${ladder.join(", ")}.`,
  ];

  return {
    ...base,
    decision: selectedLadderPct > 0 ? base.decision : base.decision === "blocked" ? "blocked" : "deferred",
    mode: modeForStep(selectedLadderPct),
    size: finalSize,
    normalizedSize,
    selectedLadderPct,
    ladder: ladder.slice(),
    reasons: [...base.reasons, ...sizingRationale],
    sizingRationale,
  };
}

function constraintsFromNeeds(needs: DetectedNeed[]): SizingConstraint[] {
  return needs.flatMap((need): SizingConstraint[] => {
    if (need.category === "reduce-exposure" && need.severity >= 70) {
      return [{
        id: `need:${need.category}`,
        label: "Need detection",
        type: "hard" as const,
        passed: false,
        severity: "high" as const,
        reason: need.explanation,
      }];
    }

    if (need.category === "wait" && need.severity >= 70) {
      return [{
        id: `need:${need.category}`,
        label: "Need detection",
        type: "hard" as const,
        passed: false,
        severity: "high" as const,
        reason: need.explanation,
      }];
    }

    if (need.category === "gather-evidence") {
      return [{
        id: `need:${need.category}`,
        label: "Need detection",
        type: "soft" as const,
        passed: need.severity < 60,
        severity: "medium" as const,
        reason: need.explanation,
      }];
    }

    return [];
  });
}

function needRiskPressure(needs: DetectedNeed[]) {
  return ratio(Math.max(0, ...needs
    .filter((need) => need.category === "reduce-exposure" || need.category === "wait")
    .map((need) => need.severity)));
}

function needParticipationBoost(needs: DetectedNeed[]) {
  const increase = needs.find((need) => need.category === "increase-participation");
  return increase ? ratio(increase.confidence) : 0.5;
}

function selectLadderStep(ladder: number[], allowedCapacity: number) {
  const selected = ladder.reduce((stepSelected, step) => (step <= allowedCapacity ? step : stepSelected), 0);
  if (selected > 0 || allowedCapacity <= 0) return selected;
  /* c8 ignore next */
  return ladder.find((step) => step > 0) ?? 0;
}

function normalizeLadder(ladder: readonly number[]) {
  return Array.from(new Set(ladder.map((step) => Math.max(0, numeric(step))).filter(Number.isFinite))).sort((a, b) => a - b);
}

function normalizeByCapacity(size: number, capacity: number | undefined) {
  const basis = numeric(capacity, 100);
  return basis <= 0 ? 0 : Number(clamp(size / basis, 0, 1).toFixed(6));
}

function ratio(value: unknown) {
  const parsed = numeric(value);
  return clamp(Math.abs(parsed) > 1 ? parsed / 100 : parsed, 0, 1);
}

function modeForStep(step: number): SizingResult["mode"] {
  if (step <= 0) return "none";
  if (step <= 2) return "micro";
  if (step <= 10) return "small";
  if (step <= 25) return "normal";
  if (step <= 50) return "large";
  return "maxSafe";
}

function formatPct(value: number) {
  return `${Math.round(value * 100)}%`;
}

/* c8 ignore start */
function formatNumber(value: number) {
  return Number.isInteger(value) ? String(value) : value.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
}
/* c8 ignore stop */

/* c8 ignore start */
export type SizingMode = "none" | "micro" | "small" | "normal" | "large" | "maxSafe";

export type SizingDecision = "blocked" | "deferred" | "allowed";

export type SizingConstraint = {
  id: string;
  label?: string;
  type: "hard" | "soft";
  passed: boolean;
  severity?: "low" | "medium" | "high" | "critical";
  reason?: string;
};

export type SizingInput = {
  targetRef: string;
  actionRef?: string;
  decisionRef?: string;

  confidence: number;
  risk: number;
  utility?: number;

  availableCapacity?: number;
  requestedCapacity?: number;
  minCapacity?: number;
  maxCapacity?: number;

  constraints?: SizingConstraint[];
  context?: Record<string, unknown>;
};

export type SizingResult = {
  decision: SizingDecision;
  mode: SizingMode;
  size: number;
  normalizedSize: number;
  confidence: number;
  risk: number;
  reasons: string[];
  constraints: SizingConstraint[];
  audit: {
    cappedBy?: string[];
    blockedBy?: string[];
    requestedCapacity?: number;
    availableCapacity?: number;
    maxCapacity?: number;
  };
};

type NormalizedCapacity = {
  value: number | undefined;
  specified: boolean;
};
/* c8 ignore stop */

const CONSTRAINT_REDUCTION: Record<NonNullable<SizingConstraint["severity"]>, number> = {
  low: 0.9,
  medium: 0.75,
  high: 0.55,
  critical: 0.35,
};

const HARD_NON_BLOCKING_REDUCTION: Record<NonNullable<SizingConstraint["severity"]>, number> = {
  low: 0.8,
  medium: 0.6,
  high: 0,
  critical: 0,
};

export function sizeDecision(input: SizingInput): SizingResult {
  const reasons: string[] = [];
  const cappedBy: string[] = [];
  const blockedBy: string[] = [];
  const constraints = normalizeConstraints(input.constraints);
  const confidence = normalizeRatio(input.confidence, "Confidence", 0, reasons);
  const risk = normalizeRatio(input.risk, "Risk", 1, reasons);
  const utility = input.utility == null ? undefined : normalizeRatio(input.utility, "Utility", 0.5, reasons);
  const requestedCapacity = normalizeCapacity(input.requestedCapacity, "Requested capacity", reasons);
  const availableCapacity = normalizeCapacity(input.availableCapacity, "Available capacity", reasons);
  const minCapacity = normalizeCapacity(input.minCapacity, "Minimum capacity", reasons);
  const maxCapacity = normalizeCapacity(input.maxCapacity, "Maximum capacity", reasons);
  const audit = buildAudit(requestedCapacity.value, availableCapacity.value, maxCapacity.value);
  const blockingConstraints = constraints.filter(
    (constraint) =>
      constraint.type === "hard" &&
      !constraint.passed &&
      (constraint.severity === "high" || constraint.severity === "critical"),
  );

  if (blockingConstraints.length > 0) {
    for (const constraint of blockingConstraints) {
      blockedBy.push(constraint.id);
      reasons.push(`Blocked by ${constraintName(constraint)}.`);
      if (constraint.reason) reasons.push(constraint.reason);
    }

    return {
      decision: "blocked",
      mode: "none",
      size: 0,
      normalizedSize: 0,
      confidence,
      risk,
      reasons: unique(reasons),
      constraints,
      audit: {
        ...audit,
        blockedBy,
      },
    };
  }

  let normalizedSize = confidence * (1 - risk);

  if (confidence <= 0) {
    reasons.push("Confidence is zero; sizing starts at zero.");
  } else if (confidence < 0.35) {
    reasons.push(`Confidence ${formatPercent(confidence)} is low; sizing is conservative.`);
  } else if (confidence < 0.6) {
    reasons.push(`Confidence ${formatPercent(confidence)} is moderate; sizing remains limited.`);
  } else {
    reasons.push(`Confidence ${formatPercent(confidence)} supports sizing.`);
  }

  if (risk >= 1) {
    reasons.push("Risk is at maximum; sizing starts at zero.");
  } else if (risk > 0.75) {
    reasons.push(`Risk ${formatPercent(risk)} is high; sizing is reduced.`);
  } else if (risk > 0.45) {
    reasons.push(`Risk ${formatPercent(risk)} is moderate; sizing is controlled.`);
  } else {
    reasons.push(`Risk ${formatPercent(risk)} is controlled.`);
  }

  if (utility != null) {
    const utilityMultiplier = 0.8 + utility * 0.4;
    normalizedSize *= utilityMultiplier;
    if (utility < 0.4) reasons.push(`Utility ${formatPercent(utility)} reduces sizing.`);
    if (utility > 0.7) reasons.push(`Utility ${formatPercent(utility)} supports sizing.`);
  }

  const failedNonBlocking = constraints.filter((constraint) => !constraint.passed);
  for (const constraint of failedNonBlocking) {
    const severity = constraint.severity as NonNullable<SizingConstraint["severity"]>;
    const factor =
      constraint.type === "hard"
        ? HARD_NON_BLOCKING_REDUCTION[severity]
        : CONSTRAINT_REDUCTION[severity];
    normalizedSize *= factor;
    reasons.push(`${constraintName(constraint)} failed with ${severity} severity; sizing reduced.`);
    if (constraint.reason) reasons.push(constraint.reason);
  }

  if (constraints.length > 0 && failedNonBlocking.length === 0) {
    reasons.push("All sizing constraints passed.");
  }

  if (confidence >= 0.75 && risk <= 0.35 && failedNonBlocking.length === 0) {
    normalizedSize *= 1.15;
    reasons.push("Strong confidence and controlled risk support increased sizing.");
  }

  normalizedSize = clampUnit(normalizedSize);

  const basis = capacityBasis(availableCapacity, requestedCapacity, maxCapacity);
  if (basis <= 0) {
    reasons.push("Available sizing capacity is zero.");
    return finalize({
      decision: "deferred",
      size: 0,
      normalizedSize: 0,
      confidence,
      risk,
      reasons,
      constraints,
      audit,
      cappedBy,
    });
  }

  let size = normalizedSize * basis;
  size = applyCap("requestedCapacity", requestedCapacity.value, size, cappedBy, reasons);
  size = applyCap("maxCapacity", maxCapacity.value, size, cappedBy, reasons);
  size = applyCap("availableCapacity", availableCapacity.value, size, cappedBy, reasons);

  if (minCapacity.value != null && minCapacity.value > 0 && normalizedSize > 0 && size > 0 && size < minCapacity.value) {
    const upperCap = smallestDefined(requestedCapacity.value, maxCapacity.value, availableCapacity.value);
    if (minCapacity.value <= upperCap) {
      size = minCapacity.value;
      reasons.push(`Raised to minimum capacity ${formatNumber(minCapacity.value)}.`);
    } else {
      reasons.push(`Minimum capacity ${formatNumber(minCapacity.value)} could not be met within caps.`);
    }
  }

  size = Math.max(0, size);
  const finalNormalizedSize = clampUnit(size / basis);

  if (finalNormalizedSize === 0) {
    reasons.push("No capacity committed after confidence, risk, constraints, and caps.");
  }

  return finalize({
    decision: finalNormalizedSize > 0 ? "allowed" : "deferred",
    size: round(size),
    normalizedSize: finalNormalizedSize,
    confidence,
    risk,
    reasons,
    constraints,
    audit,
    cappedBy,
    });
}

function finalize(args: {
  decision: SizingDecision;
  size: number;
  normalizedSize: number;
  confidence: number;
  risk: number;
  reasons: string[];
  constraints: SizingConstraint[];
  audit: SizingResult["audit"];
  cappedBy: string[];
}): SizingResult {
  return {
    decision: args.decision,
    mode: modeFor(args.normalizedSize),
    size: round(args.size),
    normalizedSize: round(clampUnit(args.normalizedSize)),
    confidence: args.confidence,
    risk: args.risk,
    reasons: unique(args.reasons),
    constraints: args.constraints,
    audit: {
      ...args.audit,
      ...(args.cappedBy.length ? { cappedBy: unique(args.cappedBy) } : {}),
    },
  };
}

function normalizeConstraints(constraints: SizingInput["constraints"]): SizingConstraint[] {
  if (!Array.isArray(constraints)) return [];
  return constraints.map((constraint, index) => ({
    id: String(constraint.id || `constraint-${index + 1}`),
    label: constraint.label,
    type: constraint.type === "hard" ? "hard" : "soft",
    passed: Boolean(constraint.passed),
    severity: normalizeSeverity(constraint.severity),
    reason: constraint.reason,
  }));
}

function normalizeSeverity(severity: SizingConstraint["severity"]): NonNullable<SizingConstraint["severity"]> {
  return severity === "low" || severity === "medium" || severity === "high" || severity === "critical"
    ? severity
    : "medium";
}

function normalizeRatio(value: unknown, label: string, fallback: number, reasons: string[]) {
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) {
    reasons.push(`${label} was missing or invalid; using ${formatPercent(fallback)}.`);
    return fallback;
  }

  const scaled = Math.abs(numberValue) > 1 ? numberValue / 100 : numberValue;
  const clamped = clampUnit(scaled);
  if (clamped !== scaled) {
    reasons.push(`${label} was outside 0-100%; clamped to ${formatPercent(clamped)}.`);
  }

  return clamped;
}

function normalizeCapacity(value: unknown, label: string, reasons: string[]): NormalizedCapacity {
  if (value == null) return { value: undefined, specified: false };
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) {
    reasons.push(`${label} was invalid and ignored.`);
    return { value: undefined, specified: true };
  }
  if (numberValue < 0) {
    reasons.push(`${label} was below zero; using 0.`);
    return { value: 0, specified: true };
  }
  return { value: numberValue, specified: true };
}

function buildAudit(
  requestedCapacity: number | undefined,
  availableCapacity: number | undefined,
  maxCapacity: number | undefined,
): SizingResult["audit"] {
  return {
    ...(requestedCapacity != null ? { requestedCapacity } : {}),
    ...(availableCapacity != null ? { availableCapacity } : {}),
    ...(maxCapacity != null ? { maxCapacity } : {}),
  };
}

function capacityBasis(
  availableCapacity: NormalizedCapacity,
  requestedCapacity: NormalizedCapacity,
  maxCapacity: NormalizedCapacity,
) {
  const capacities = [availableCapacity, requestedCapacity, maxCapacity]
    .filter((capacity) => capacity.specified)
    .map((capacity) => capacity.value ?? 0);
  if (capacities.length > 0) return Math.max(...capacities);
  return 1;
}

function applyCap(
  name: "requestedCapacity" | "availableCapacity" | "maxCapacity",
  cap: number | undefined,
  size: number,
  cappedBy: string[],
  reasons: string[],
) {
  if (cap == null || size <= cap) return size;
  cappedBy.push(name);
  reasons.push(`Capped by ${name} at ${formatNumber(cap)}.`);
  return cap;
}

function smallestDefined(...values: Array<number | undefined>) {
  const defined = values.filter((value): value is number => value != null);
  return defined.length ? Math.min(...defined) : Number.POSITIVE_INFINITY;
}

function constraintName(constraint: SizingConstraint) {
  return constraint.label ? `${constraint.label} (${constraint.id})` : constraint.id;
}

function modeFor(normalizedSize: number): SizingMode {
  if (normalizedSize <= 0) return "none";
  if (normalizedSize <= 0.05) return "micro";
  if (normalizedSize <= 0.15) return "small";
  if (normalizedSize <= 0.4) return "normal";
  if (normalizedSize <= 0.7) return "large";
  return "maxSafe";
}

function clampUnit(value: number) {
  /* c8 ignore next */
  if (!Number.isFinite(value)) return 0;
  return Math.min(1, Math.max(0, value));
}

function round(value: number) {
  return Number(value.toFixed(6));
}

function formatPercent(value: number) {
  return `${Math.round(value * 100)}%`;
}

function formatNumber(value: number) {
  return Number.isInteger(value) ? String(value) : value.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
}

/* c8 ignore next 3 */
function unique(values: string[]) {
  return Array.from(new Set(values));
}

import { clamp, mean, numeric } from "../math/statistics";

export type ViabilityVerdict = "viable" | "marginal" | "not-viable" | "blocked";

export type ViabilitySeverity = "low" | "medium" | "high" | "critical";

export type ViabilityConstraintOperator = "<" | "<=" | ">" | ">=" | "==" | "!=";

export type ViabilityConstraintInput = {
  id: string;
  label?: string;
  type?: "hard" | "soft" | string;
  dimension?: string;
  hard?: boolean;
  passed?: boolean;
  value?: number | string | boolean | null;
  limit?: number | string | boolean | null;
  min?: number;
  max?: number;
  operator?: ViabilityConstraintOperator;
  severity?: ViabilitySeverity | string;
  weight?: number;
  reason?: string;
  warning?: string;
  blocker?: boolean;
  metadata?: Record<string, unknown>;
};

export type ViabilityConstraintResult = {
  id: string;
  label: string;
  type: string;
  dimension?: string;
  hard: boolean;
  severity: ViabilitySeverity;
  passed: boolean;
  score: number;
  weight: number;
  reason: string;
  warning?: string;
  blocker: boolean;
  metadata?: Record<string, unknown>;
};

export type ViabilityInput = {
  targetRef: string;
  actionRef?: string;
  decisionRef?: string;
  expectedBenefit: number;
  expectedCost: number;
  expectedRisk: number;
  uncertainty?: number;
  confidence?: number;
  constraints?: ViabilityConstraintInput[];
  minMarginOfSafety?: number;
  thresholds?: {
    minConfidence?: number;
    maxCost?: number;
    maxRisk?: number;
    maxUncertainty?: number;
  };
  weights?: {
    benefit?: number;
    cost?: number;
    risk?: number;
    uncertainty?: number;
  };
  context?: Record<string, unknown>;
};

export type ViabilityResult = {
  targetRef: string;
  actionRef?: string;
  decisionRef?: string;
  verdict: ViabilityVerdict;
  finalVerdict: ViabilityVerdict;
  score: number;
  expectedBenefit: number;
  expectedCost: number;
  expectedRisk: number;
  uncertainty: number;
  confidence: number;
  marginOfSafety: number;
  requiredMarginOfSafety: number;
  constraints: ViabilityConstraintResult[];
  blockers: string[];
  warnings: string[];
  reasons: string[];
  audit: {
    componentScores: {
      expectedBenefit: number;
      expectedCost: number;
      expectedRisk: number;
      uncertainty: number;
      confidence: number;
      constraintScore: number;
      marginScore: number;
    };
    weights: {
      benefit: number;
      cost: number;
      risk: number;
      uncertainty: number;
    };
    thresholds: {
      minConfidence: number;
      maxCost: number;
      maxRisk: number;
      maxUncertainty: number;
      minMarginOfSafety: number;
    };
    formulas: string[];
  };
};

type NormalizedViability = {
  benefit: number;
  cost: number;
  risk: number;
  uncertainty: number;
  confidence: number;
  weights: Required<NonNullable<ViabilityInput["weights"]>>;
};

const DEFAULT_WEIGHTS: Required<NonNullable<ViabilityInput["weights"]>> = {
  benefit: 1,
  cost: 0.35,
  risk: 0.45,
  uncertainty: 0.2,
};

const DEFAULT_THRESHOLDS = {
  minConfidence: 0.35,
  maxCost: 0.85,
  maxRisk: 0.8,
  maxUncertainty: 0.7,
  minMarginOfSafety: 0.05,
};

const FAILED_CONSTRAINT_SCORE: Record<ViabilitySeverity, number> = {
  low: 72,
  medium: 52,
  high: 24,
  critical: 0,
};

export function evaluateViability(input: ViabilityInput): ViabilityResult {
  const normalized = normalizeViability(input);
  const constraints = normalizeConstraints(input.constraints);
  const constraintScore = weightedConstraintScore(constraints);
  const requiredMarginOfSafety = normalizeMargin(
    input.minMarginOfSafety,
    DEFAULT_THRESHOLDS.minMarginOfSafety,
  );
  const thresholds = {
    minConfidence: ratio(input.thresholds?.minConfidence, DEFAULT_THRESHOLDS.minConfidence),
    maxCost: ratio(input.thresholds?.maxCost, DEFAULT_THRESHOLDS.maxCost),
    maxRisk: ratio(input.thresholds?.maxRisk, DEFAULT_THRESHOLDS.maxRisk),
    maxUncertainty: ratio(input.thresholds?.maxUncertainty, DEFAULT_THRESHOLDS.maxUncertainty),
    minMarginOfSafety: requiredMarginOfSafety,
  };
  const marginOfSafety = calculateMarginOfSafety(input);
  const blockers = constraints
    .filter((constraint) => constraint.blocker)
    .map((constraint) => constraintName(constraint));
  const warnings = collectWarnings({
    normalized,
    constraints,
    thresholds,
    marginOfSafety,
    blockers,
  });
  const verdict = resolveVerdict({
    marginOfSafety,
    requiredMarginOfSafety,
    normalized,
    thresholds,
    blockers,
    warnings,
  });
  const marginScore = clamp(50 + marginOfSafety * 100);
  const rawScore = clamp(
    marginScore * 0.55 +
      constraintScore * 0.25 +
      normalized.confidence * 100 * 0.2,
  );
  const score = capScoreByVerdict(rawScore, verdict);
  const result: ViabilityResult = {
    targetRef: String(input.targetRef ?? "target"),
    actionRef: input.actionRef,
    decisionRef: input.decisionRef,
    verdict,
    finalVerdict: verdict,
    score: roundScore(score),
    expectedBenefit: roundUnit(normalized.benefit),
    expectedCost: roundUnit(normalized.cost),
    expectedRisk: roundUnit(normalized.risk),
    uncertainty: roundUnit(normalized.uncertainty),
    confidence: roundUnit(normalized.confidence),
    marginOfSafety,
    requiredMarginOfSafety: roundUnit(requiredMarginOfSafety),
    constraints,
    blockers: unique(blockers),
    warnings,
    reasons: [],
    audit: {
      componentScores: {
        expectedBenefit: roundUnit(normalized.benefit),
        expectedCost: roundUnit(normalized.cost),
        expectedRisk: roundUnit(normalized.risk),
        uncertainty: roundUnit(normalized.uncertainty),
        confidence: roundUnit(normalized.confidence),
        constraintScore: roundScore(constraintScore),
        marginScore: roundScore(marginScore),
      },
      weights: normalized.weights,
      thresholds,
      formulas: [
        "adjustedBenefit = expectedBenefit * (0.5 + confidence * 0.5)",
        "expectedDrag = expectedCost * costWeight + expectedRisk * riskWeight + uncertainty * uncertaintyWeight",
        "marginOfSafety = adjustedBenefit * benefitWeight - expectedDrag",
      ],
    },
  };

  return {
    ...result,
    reasons: unique([
      createViabilityReason(result),
      ...constraints
        .filter((constraint) => !constraint.passed)
        .map((constraint) => constraint.reason),
      ...warnings,
    ]),
  };
}

export function evaluateViabilityConstraint(
  input: ViabilityConstraintInput,
): ViabilityConstraintResult {
  const id = String(input.id || "constraint");
  const label = input.label || id;
  const hard = input.hard ?? input.type === "hard";
  const type = input.type || (hard ? "hard" : "soft");
  const severity = normalizeSeverity(input.severity);
  const evaluation = evaluateConstraintPass(input);
  const blocker =
    !evaluation.passed &&
    (input.blocker === true ||
      (hard && (severity === "high" || severity === "critical")));
  const reason =
    input.reason ??
    evaluation.reason ??
    `${label} ${evaluation.passed ? "passed" : "failed"}.`;

  return {
    id,
    label,
    type,
    dimension: input.dimension,
    hard,
    severity,
    passed: evaluation.passed,
    score: evaluation.passed ? 100 : FAILED_CONSTRAINT_SCORE[severity],
    weight: positive(input.weight, 1),
    reason,
    warning: !evaluation.passed && !blocker ? input.warning ?? reason : input.warning,
    blocker,
    metadata: input.metadata,
  };
}

export function calculateMarginOfSafety(input: ViabilityInput): number {
  const normalized = normalizeViability(input);
  const adjustedBenefit =
    normalized.benefit *
    normalized.weights.benefit *
    (0.5 + normalized.confidence * 0.5);
  const expectedDrag =
    normalized.cost * normalized.weights.cost +
    normalized.risk * normalized.weights.risk +
    normalized.uncertainty * normalized.weights.uncertainty;
  return roundMargin(clamp(adjustedBenefit - expectedDrag, -100, 100));
}

export function createViabilityReason(result: ViabilityResult): string {
  const margin = formatSignedPercent(result.marginOfSafety);
  const confidence = formatPercent(result.confidence);

  if (result.verdict === "blocked") {
    const blocker = result.blockers[0] ?? "a hard constraint";
    return `Blocked: ${blocker} prevents the action despite a ${margin} margin of safety.`;
  }

  if (result.verdict === "not-viable") {
    return `Not viable: expected benefit does not clear cost, risk, and uncertainty with enough safety margin (${margin}, confidence ${confidence}).`;
  }

  if (result.verdict === "marginal") {
    return `Marginal: the action clears the basic viability check with a thin ${margin} margin of safety at ${confidence} confidence.`;
  }

  return `Viable: expected benefit clears cost, risk, and uncertainty with a ${margin} margin of safety at ${confidence} confidence.`;
}

function normalizeViability(input: ViabilityInput): NormalizedViability {
  const uncertaintySeed =
    input.uncertainty == null && input.confidence != null
      ? 1 - ratio(input.confidence, 0.5)
      : 0.5;
  const uncertainty = ratio(input.uncertainty, uncertaintySeed);
  const confidence = ratio(input.confidence, 1 - uncertainty);

  return {
    benefit: ratio(input.expectedBenefit, 0),
    cost: ratio(input.expectedCost, 0),
    risk: ratio(input.expectedRisk, 0),
    uncertainty,
    confidence,
    weights: {
      benefit: positive(input.weights?.benefit, DEFAULT_WEIGHTS.benefit),
      cost: positive(input.weights?.cost, DEFAULT_WEIGHTS.cost),
      risk: positive(input.weights?.risk, DEFAULT_WEIGHTS.risk),
      uncertainty: positive(input.weights?.uncertainty, DEFAULT_WEIGHTS.uncertainty),
    },
  };
}

function normalizeConstraints(
  constraints: ViabilityInput["constraints"],
): ViabilityConstraintResult[] {
  if (!Array.isArray(constraints)) return [];
  return constraints.map((constraint, index) =>
    evaluateViabilityConstraint({
      ...constraint,
      id: constraint.id || `constraint-${index + 1}`,
    }),
  );
}

function evaluateConstraintPass(input: ViabilityConstraintInput): {
  passed: boolean;
  reason?: string;
} {
  if (typeof input.passed === "boolean") {
    return { passed: input.passed };
  }

  if (input.operator) {
    return evaluateOperator(input);
  }

  const value = Number(input.value);
  if (Number.isFinite(value) && (input.min != null || input.max != null)) {
    const aboveMin = input.min == null || value >= input.min;
    const belowMax = input.max == null || value <= input.max;
    return {
      passed: aboveMin && belowMax,
      reason: `Value ${formatNumber(value)} must be between ${formatBoundary(input.min, "-infinity")} and ${formatBoundary(input.max, "infinity")}.`,
    };
  }

  if (typeof input.value === "boolean") {
    return { passed: input.value };
  }

  return {
    passed: true,
    reason: "Constraint supplied without an evaluable rule; treated as informational.",
  };
}

function evaluateOperator(input: ViabilityConstraintInput): {
  passed: boolean;
  reason: string;
} {
  const left = Number(input.value);
  const right = Number(input.limit);
  const operator = input.operator as ViabilityConstraintOperator;
  const numericComparison = Number.isFinite(left) && Number.isFinite(right);

  if (numericComparison) {
    return {
      passed: compareNumbers(left, right, operator),
      reason: `Value ${formatNumber(left)} must be ${operator} ${formatNumber(right)}.`,
    };
  }

  if (operator === "==" || operator === "!=") {
    const passed =
      operator === "=="
        ? Object.is(input.value, input.limit)
        : !Object.is(input.value, input.limit);
    return {
      passed,
      reason: `Value must be ${operator} ${String(input.limit)}.`,
    };
  }

  return {
    passed: false,
    reason: "Constraint could not be evaluated from non-numeric values.",
  };
}

function compareNumbers(
  left: number,
  right: number,
  operator: ViabilityConstraintOperator,
) {
  if (operator === "<") return left < right;
  if (operator === "<=") return left <= right;
  if (operator === ">") return left > right;
  if (operator === ">=") return left >= right;
  if (operator === "==") return left === right;
  return left !== right;
}

function collectWarnings(args: {
  normalized: NormalizedViability;
  constraints: ViabilityConstraintResult[];
  thresholds: ViabilityResult["audit"]["thresholds"];
  marginOfSafety: number;
  blockers: string[];
}) {
  const warnings: string[] = [];
  if (args.normalized.confidence < args.thresholds.minConfidence) {
    warnings.push(
      `Confidence ${formatPercent(args.normalized.confidence)} is below the minimum ${formatPercent(args.thresholds.minConfidence)}.`,
    );
  }
  if (args.normalized.cost > args.thresholds.maxCost) {
    warnings.push(
      `Expected cost ${formatPercent(args.normalized.cost)} exceeds the maximum ${formatPercent(args.thresholds.maxCost)}.`,
    );
  }
  if (args.normalized.risk > args.thresholds.maxRisk) {
    warnings.push(
      `Expected risk ${formatPercent(args.normalized.risk)} exceeds the maximum ${formatPercent(args.thresholds.maxRisk)}.`,
    );
  }
  if (args.normalized.uncertainty > args.thresholds.maxUncertainty) {
    warnings.push(
      `Uncertainty ${formatPercent(args.normalized.uncertainty)} exceeds the maximum ${formatPercent(args.thresholds.maxUncertainty)}.`,
    );
  }
  if (args.marginOfSafety < args.thresholds.minMarginOfSafety) {
    warnings.push(
      `Margin of safety ${formatSignedPercent(args.marginOfSafety)} is below the required ${formatPercent(args.thresholds.minMarginOfSafety)}.`,
    );
  }

  for (const constraint of args.constraints) {
    if (constraint.warning) warnings.push(constraint.warning);
  }

  if (args.blockers.length) {
    warnings.push(`Blocked by ${args.blockers.join(", ")}.`);
  }

  return unique(warnings);
}

function resolveVerdict(args: {
  marginOfSafety: number;
  requiredMarginOfSafety: number;
  normalized: NormalizedViability;
  thresholds: ViabilityResult["audit"]["thresholds"];
  blockers: string[];
  warnings: string[];
}): ViabilityVerdict {
  if (args.blockers.length > 0) return "blocked";
  if (args.marginOfSafety < 0) return "not-viable";

  const thresholdPressure =
    args.normalized.confidence < args.thresholds.minConfidence ||
    args.normalized.cost > args.thresholds.maxCost ||
    args.normalized.risk > args.thresholds.maxRisk ||
    args.normalized.uncertainty > args.thresholds.maxUncertainty;

  if (args.marginOfSafety < args.requiredMarginOfSafety) return "marginal";
  if (thresholdPressure || args.warnings.length > 0) return "marginal";
  return "viable";
}

function weightedConstraintScore(constraints: ViabilityConstraintResult[]) {
  if (!constraints.length) return 100;
  const totalWeight = constraints.reduce((sum, constraint) => sum + constraint.weight, 0);
  if (totalWeight <= 0) return mean(constraints.map((constraint) => constraint.score));
  return constraints.reduce(
    (sum, constraint) => sum + constraint.score * constraint.weight,
    0,
  ) / totalWeight;
}

function capScoreByVerdict(score: number, verdict: ViabilityVerdict) {
  if (verdict === "blocked") return Math.min(score, 20);
  if (verdict === "not-viable") return Math.min(score, 49);
  if (verdict === "marginal") return Math.min(score, 69);
  return score;
}

function normalizeSeverity(severity: ViabilityConstraintInput["severity"]): ViabilitySeverity {
  return severity === "low" ||
    severity === "medium" ||
    severity === "high" ||
    severity === "critical"
    ? severity
    : "medium";
}

function ratio(value: unknown, fallback: number) {
  const parsed = numeric(value, fallback);
  const scaled = Math.abs(parsed) > 1 ? parsed / 100 : parsed;
  return clamp(scaled, 0, 1);
}

function positive(value: unknown, fallback: number) {
  const parsed = numeric(value, fallback);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function normalizeMargin(value: unknown, fallback: number) {
  const parsed = numeric(value, fallback);
  if (!Number.isFinite(parsed)) return fallback;
  if (Math.abs(parsed) > 1) return clamp(parsed / 100, -1, 1);
  return clamp(parsed, -1, 1);
}

function constraintName(constraint: ViabilityConstraintResult) {
  return constraint.label && constraint.label !== constraint.id
    ? `${constraint.label} (${constraint.id})`
    : constraint.id;
}

function roundUnit(value: number) {
  return Number(value.toFixed(6));
}

function roundScore(value: number) {
  return Number(value.toFixed(2));
}

function roundMargin(value: number) {
  return Number(value.toFixed(6));
}

function formatPercent(value: number) {
  return `${Math.round(value * 100)}%`;
}

function formatSignedPercent(value: number) {
  const rounded = Math.round(value * 100);
  return `${rounded >= 0 ? "+" : ""}${rounded}%`;
}

function formatNumber(value: number) {
  return Number.isInteger(value) ? String(value) : value.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
}

function formatBoundary(value: number | undefined, fallback: string) {
  return value == null ? fallback : formatNumber(value);
}

function unique(values: string[]) {
  return Array.from(new Set(values.filter(Boolean)));
}

/* c8 ignore next */
import { clamp, mean, stdev } from "../math/statistics";

